const t = (en: string, hi: string, pa: string): SifLocalizedText => ({ "en-IN": en, "hi-IN": hi, "pa-IN": pa });
const fact = (id: string, text: SifLocalizedText) => ({ id, text });
const candidate = (id: string, text: SifLocalizedText, follows: boolean, strength: SifCandidateAuthority["strength"], supportFactIds: readonly string[], distractorType?: SifCandidateAuthority["distractorType"]): SifCandidateAuthority => ({ id, text, follows, strength, supportFactIds, ...(distractorType ? { distractorType } : {}) });
const guard = { evaluatesSupport: true, assumptionQuestion: false, conclusionQuestion: false, argumentQuestion: false, causeEffectQuestion: false, courseOfActionQuestion: false } as const;

function scenario(input: Omit<SifScenarioAuthority, "identityGuard">): SifScenarioAuthority {
  return { ...input, identityGuard: guard };
}

