const primary: readonly SifScenarioAuthority[] = [
  scenario({ id: "SIF-CP001-DIRECT", cpId: "SIF-CP001", difficulty: "EASY", domain: "EDUCATION", mechanisms: ["DIRECT_FACT"], statement: t("Rohan submitted the scholarship form on Tuesday and received an acknowledgement the same day.", "रोहन ने मंगलवार को छात्रवृत्ति फॉर्म जमा किया और उसी दिन पावती प्राप्त की।", "ਰੋਹਨ ਨੇ ਮੰਗਲਵਾਰ ਨੂੰ ਵਜ਼ੀਫ਼ੇ ਦਾ ਫਾਰਮ ਜਮ੍ਹਾਂ ਕੀਤਾ ਅਤੇ ਉਸੇ ਦਿਨ ਰਸੀਦ ਪ੍ਰਾਪਤ ਕੀਤੀ।"), facts: [fact("F1", t("Rohan submitted the form on Tuesday.", "रोहन ने मंगलवार को फॉर्म जमा किया।", "ਰੋਹਨ ਨੇ ਮੰਗਲਵਾਰ ਨੂੰ ਫਾਰਮ ਜਮ੍ਹਾਂ ਕੀਤਾ।")), fact("F2", t("He received an acknowledgement that day.", "उसे उसी दिन पावती मिली।", "ਉਸ ਨੂੰ ਉਸੇ ਦਿਨ ਰਸੀਦ ਮਿਲੀ।"))], candidates: [candidate("I", t("The office acknowledged receipt of Rohan's form on Tuesday.", "कार्यालय ने मंगलवार को रोहन के फॉर्म की प्राप्ति स्वीकार की।", "ਦਫ਼ਤਰ ਨੇ ਮੰਗਲਵਾਰ ਨੂੰ ਰੋਹਨ ਦਾ ਫਾਰਮ ਮਿਲਣ ਦੀ ਪੁਸ਼ਟੀ ਕੀਤੀ।"), true, "CERTAIN", ["F1", "F2"]), candidate("II", t("Rohan's scholarship was approved on Tuesday.", "रोहन की छात्रवृत्ति मंगलवार को मंजूर हो गई।", "ਰੋਹਨ ਦਾ ਵਜ਼ੀਫ਼ਾ ਮੰਗਲਵਾਰ ਨੂੰ ਮਨਜ਼ੂਰ ਹੋ ਗਿਆ।"), false, "UNSUPPORTED_OR_CONTRADICTED", ["F2"], "UNSUPPORTED_DETAIL")], explanation: t("The acknowledgement confirms receipt of the form, not approval of the scholarship. Therefore, only I follows.", "पावती केवल फॉर्म प्राप्त होने की पुष्टि करती है, छात्रवृत्ति मंजूर होने की नहीं। इसलिए केवल I सही है।", "ਰਸੀਦ ਸਿਰਫ਼ ਫਾਰਮ ਮਿਲਣ ਦੀ ਪੁਸ਼ਟੀ ਕਰਦੀ ਹੈ, ਵਜ਼ੀਫ਼ਾ ਮਨਜ਼ੂਰ ਹੋਣ ਦੀ ਨਹੀਂ। ਇਸ ਲਈ ਕੇਵਲ I ਸਹੀ ਹੈ।") }),
  scenario({ id: "SIF-CP010-CONDITIONAL", cpId: "SIF-CP010", difficulty: "HARD", domain: "WORKPLACE", mechanisms: ["CONDITIONAL_DIRECTION"], statement: t("Employees receive the field allowance only if they work in a designated area.", "कर्मचारियों को क्षेत्र भत्ता तभी मिलता है जब वे निर्धारित क्षेत्र में काम करते हैं।", "ਕਰਮਚਾਰੀਆਂ ਨੂੰ ਫੀਲਡ ਭੱਤਾ ਕੇਵਲ ਤਾਂ ਹੀ ਮਿਲਦਾ ਹੈ ਜੇ ਉਹ ਨਿਰਧਾਰਤ ਖੇਤਰ ਵਿੱਚ ਕੰਮ ਕਰਦੇ ਹਨ।"), facts: [fact("F1", t("Working in a designated area is necessary for receiving the allowance.", "निर्धारित क्षेत्र में काम करना भत्ता पाने के लिए आवश्यक है।", "ਨਿਰਧਾਰਤ ਖੇਤਰ ਵਿੱਚ ਕੰਮ ਕਰਨਾ ਭੱਤਾ ਲੈਣ ਲਈ ਲਾਜ਼ਮੀ ਹੈ।"))], candidates: [candidate("I", t("An employee who receives the allowance works in a designated area.", "भत्ता पाने वाला कर्मचारी निर्धारित क्षेत्र में काम करता है।", "ਭੱਤਾ ਲੈਣ ਵਾਲਾ ਕਰਮਚਾਰੀ ਨਿਰਧਾਰਤ ਖੇਤਰ ਵਿੱਚ ਕੰਮ ਕਰਦਾ ਹੈ।"), true, "CERTAIN", ["F1"]), candidate("II", t("Every employee working in a designated area receives the allowance.", "निर्धारित क्षेत्र में काम करने वाला हर कर्मचारी भत्ता पाता है।", "ਨਿਰਧਾਰਤ ਖੇਤਰ ਵਿੱਚ ਕੰਮ ਕਰਨ ਵਾਲਾ ਹਰ ਕਰਮਚਾਰੀ ਭੱਤਾ ਲੈਂਦਾ ਹੈ।"), false, "POSSIBLE_ONLY", ["F1"], "REVERSED_RELATIONSHIP")], explanation: t("‘Only if’ makes designated-area work necessary for receiving the allowance. It does not make it sufficient. Therefore, only I follows.", "‘तभी’ निर्धारित क्षेत्र में काम करने को भत्ता पाने की आवश्यक शर्त बनाता है, पर्याप्त शर्त नहीं। इसलिए केवल I सही है।", "‘ਕੇਵਲ ਤਾਂ ਹੀ’ ਨਿਰਧਾਰਤ ਖੇਤਰ ਵਿੱਚ ਕੰਮ ਕਰਨ ਨੂੰ ਭੱਤਾ ਲੈਣ ਦੀ ਲਾਜ਼ਮੀ ਸ਼ਰਤ ਬਣਾਉਂਦਾ ਹੈ, ਕਾਫ਼ੀ ਸ਼ਰਤ ਨਹੀਂ। ਇਸ ਲਈ ਕੇਵਲ I ਸਹੀ ਹੈ।") }),
  scenario({ id: "SIF-CP012-SUPPORT", cpId: "SIF-CP012", difficulty: "MEDIUM", domain: "WORKPLACE", mechanisms: ["SUPPORT_THRESHOLD"], statement: t("Ravi reached the office at 10:30 a.m.", "रवि सुबह 10:30 बजे कार्यालय पहुंचा।", "ਰਵੀ ਸਵੇਰੇ 10:30 ਵਜੇ ਦਫ਼ਤਰ ਪਹੁੰਚਿਆ।"), facts: [fact("F1", t("Ravi reached at 10:30 a.m.", "रवि 10:30 बजे पहुंचा।", "ਰਵੀ 10:30 ਵਜੇ ਪਹੁੰਚਿਆ।"))], candidates: [candidate("I", t("Ravi was at the office by 10:30 a.m.", "रवि 10:30 बजे तक कार्यालय पहुंच चुका था।", "ਰਵੀ 10:30 ਵਜੇ ਤੱਕ ਦਫ਼ਤਰ ਪਹੁੰਚ ਚੁੱਕਾ ਸੀ।"), true, "CERTAIN", ["F1"]), candidate("II", t("Ravi was delayed because of traffic.", "रवि यातायात के कारण देर से पहुंचा।", "ਰਵੀ ਆਵਾਜਾਈ ਕਾਰਨ ਦੇਰ ਨਾਲ ਪਹੁੰਚਿਆ।"), false, "POSSIBLE_ONLY", ["F1"], "COMMON_KNOWLEDGE")], explanation: t("The arrival time supports I. Traffic may be possible, but the statement gives no reason for Ravi's arrival time. Therefore, only I follows.", "पहुंचने का समय I का समर्थन करता है। यातायात एक संभावना हो सकती है, पर कथन कोई कारण नहीं बताता। इसलिए केवल I सही है।", "ਪਹੁੰਚਣ ਦਾ ਸਮਾਂ I ਦਾ ਸਮਰਥਨ ਕਰਦਾ ਹੈ। ਆਵਾਜਾਈ ਇੱਕ ਸੰਭਾਵਨਾ ਹੋ ਸਕਦੀ ਹੈ, ਪਰ ਕਥਨ ਕੋਈ ਕਾਰਨ ਨਹੀਂ ਦੱਸਦਾ। ਇਸ ਲਈ ਕੇਵਲ I ਸਹੀ ਹੈ।") }),
  scenario({ id: "SIF-CP013-SCOPE", cpId: "SIF-CP013", difficulty: "HARD", domain: "EDUCATION", mechanisms: ["SCOPE_CONTROL"], statement: t("In a survey at one college, 68% of the participating students preferred recorded lectures.", "एक कॉलेज में किए गए सर्वेक्षण में 68% प्रतिभागी विद्यार्थियों ने रिकॉर्डेड व्याख्यान पसंद किए।", "ਇੱਕ ਕਾਲਜ ਵਿੱਚ ਕੀਤੇ ਸਰਵੇਖਣ ਵਿੱਚ 68% ਭਾਗੀਦਾਰ ਵਿਦਿਆਰਥੀਆਂ ਨੇ ਰਿਕਾਰਡ ਕੀਤੇ ਲੈਕਚਰ ਪਸੰਦ ਕੀਤੇ।"), facts: [fact("F1", t("68% of surveyed students at one college preferred recorded lectures.", "एक कॉलेज के 68% सर्वेक्षित विद्यार्थियों ने रिकॉर्डेड व्याख्यान पसंद किए।", "ਇੱਕ ਕਾਲਜ ਦੇ 68% ਸਰਵੇਖਣ ਕੀਤੇ ਵਿਦਿਆਰਥੀਆਂ ਨੇ ਰਿਕਾਰਡ ਕੀਤੇ ਲੈਕਚਰ ਪਸੰਦ ਕੀਤੇ।"))], candidates: [candidate("I", t("A majority of the surveyed students at that college preferred recorded lectures.", "उस कॉलेज के सर्वेक्षित विद्यार्थियों में बहुमत ने रिकॉर्डेड व्याख्यान पसंद किए।", "ਉਸ ਕਾਲਜ ਦੇ ਸਰਵੇਖਣ ਕੀਤੇ ਵਿਦਿਆਰਥੀਆਂ ਵਿੱਚ ਬਹੁਮਤ ਨੇ ਰਿਕਾਰਡ ਕੀਤੇ ਲੈਕਚਰ ਪਸੰਦ ਕੀਤੇ।"), true, "CERTAIN", ["F1"]), candidate("II", t("Most college students in the country prefer recorded lectures.", "देश के अधिकांश कॉलेज विद्यार्थी रिकॉर्डेड व्याख्यान पसंद करते हैं।", "ਦੇਸ਼ ਦੇ ਜ਼ਿਆਦਾਤਰ ਕਾਲਜ ਵਿਦਿਆਰਥੀ ਰਿਕਾਰਡ ਕੀਤੇ ਲੈਕਚਰ ਪਸੰਦ ਕਰਦੇ ਹਨ।"), false, "UNSUPPORTED_OR_CONTRADICTED", ["F1"], "SCOPE_CHANGE")], explanation: t("The result applies only to surveyed students at one college. It cannot be extended to college students across the country. Therefore, only I follows.", "परिणाम केवल एक कॉलेज के सर्वेक्षित विद्यार्थियों पर लागू होता है। इसे पूरे देश के कॉलेज विद्यार्थियों पर लागू नहीं किया जा सकता। इसलिए केवल I सही है।", "ਨਤੀਜਾ ਸਿਰਫ਼ ਇੱਕ ਕਾਲਜ ਦੇ ਸਰਵੇਖਣ ਕੀਤੇ ਵਿਦਿਆਰਥੀਆਂ 'ਤੇ ਲਾਗੂ ਹੁੰਦਾ ਹੈ। ਇਸ ਨੂੰ ਦੇਸ਼ ਭਰ ਦੇ ਕਾਲਜ ਵਿਦਿਆਰਥੀਆਂ 'ਤੇ ਲਾਗੂ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ। ਇਸ ਲਈ ਕੇਵਲ I ਸਹੀ ਹੈ।") }),
  scenario({ id: "SIF-CP014-TIME", cpId: "SIF-CP014", difficulty: "MEDIUM", domain: "PUBLIC_ADMINISTRATION", mechanisms: ["TIME_SEQUENCE"], statement: t("The complaint was registered on 4 August. An inspection was conducted on 7 August, and the repair work began on 9 August.", "शिकायत 4 अगस्त को दर्ज हुई। निरीक्षण 7 अगस्त को हुआ और मरम्मत कार्य 9 अगस्त को शुरू हुआ।", "ਸ਼ਿਕਾਇਤ 4 ਅਗਸਤ ਨੂੰ ਦਰਜ ਹੋਈ। ਜਾਂਚ 7 ਅਗਸਤ ਨੂੰ ਹੋਈ ਅਤੇ ਮੁਰੰਮਤ ਦਾ ਕੰਮ 9 ਅਗਸਤ ਨੂੰ ਸ਼ੁਰੂ ਹੋਇਆ।"), facts: [fact("F1", t("Complaint preceded inspection.", "शिकायत निरीक्षण से पहले हुई।", "ਸ਼ਿਕਾਇਤ ਜਾਂਚ ਤੋਂ ਪਹਿਲਾਂ ਹੋਈ।")), fact("F2", t("Inspection preceded repair.", "निरीक्षण मरम्मत से पहले हुआ।", "ਜਾਂਚ ਮੁਰੰਮਤ ਤੋਂ ਪਹਿਲਾਂ ਹੋਈ।"))], candidates: [candidate("I", t("The inspection took place after the complaint was registered but before repair work began.", "निरीक्षण शिकायत दर्ज होने के बाद और मरम्मत शुरू होने से पहले हुआ।", "ਜਾਂਚ ਸ਼ਿਕਾਇਤ ਦਰਜ ਹੋਣ ਤੋਂ ਬਾਅਦ ਅਤੇ ਮੁਰੰਮਤ ਸ਼ੁਰੂ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਹੋਈ।"), true, "CERTAIN", ["F1", "F2"]), candidate("II", t("The complaint caused the repair work to begin.", "शिकायत के कारण मरम्मत कार्य शुरू हुआ।", "ਸ਼ਿਕਾਇਤ ਕਾਰਨ ਮੁਰੰਮਤ ਦਾ ਕੰਮ ਸ਼ੁਰੂ ਹੋਇਆ।"), false, "POSSIBLE_ONLY", ["F1", "F2"], "CAUSE_ASSUMPTION")], explanation: t("The dates establish the sequence in I. A sequence alone does not establish causation, so II does not follow.", "तिथियां I में दिया क्रम स्थापित करती हैं। केवल क्रम से कारण सिद्ध नहीं होता, इसलिए II सही नहीं है।", "ਤਾਰੀਖਾਂ I ਵਿੱਚ ਦਿੱਤਾ ਕ੍ਰਮ ਸਥਾਪਿਤ ਕਰਦੀਆਂ ਹਨ। ਸਿਰਫ਼ ਕ੍ਰਮ ਨਾਲ ਕਾਰਨ ਸਾਬਤ ਨਹੀਂ ਹੁੰਦਾ, ਇਸ ਲਈ II ਸਹੀ ਨਹੀਂ ਹੈ।") }),
  scenario({ id: "SIF-CP015-POSITION", cpId: "SIF-CP015", difficulty: "MEDIUM", domain: "PUBLIC_ADMINISTRATION", mechanisms: ["STATED_POSITION"], statement: t("The residents' association welcomed the new bus service but asked the transport department to add an early-morning trip.", "निवासी संघ ने नई बस सेवा का स्वागत किया, लेकिन परिवहन विभाग से सुबह की एक अतिरिक्त यात्रा जोड़ने को कहा।", "ਰਿਹਾਇਸ਼ੀ ਸੰਘ ਨੇ ਨਵੀਂ ਬੱਸ ਸੇਵਾ ਦਾ ਸਵਾਗਤ ਕੀਤਾ, ਪਰ ਆਵਾਜਾਈ ਵਿਭਾਗ ਨੂੰ ਸਵੇਰੇ ਦੀ ਇੱਕ ਹੋਰ ਟ੍ਰਿਪ ਜੋੜਨ ਲਈ ਕਿਹਾ।"), facts: [fact("F1", t("The association welcomed the service.", "संघ ने सेवा का स्वागत किया।", "ਸੰਘ ਨੇ ਸੇਵਾ ਦਾ ਸਵਾਗਤ ਕੀਤਾ।")), fact("F2", t("It requested an early-morning trip.", "उसने सुबह की यात्रा मांगी।", "ਉਸ ਨੇ ਸਵੇਰੇ ਦੀ ਟ੍ਰਿਪ ਮੰਗੀ।"))], candidates: [candidate("I", t("The association supported the service while seeking an improvement in its schedule.", "संघ ने सेवा का समर्थन किया और समय-सारणी में सुधार मांगा।", "ਸੰਘ ਨੇ ਸੇਵਾ ਦਾ ਸਮਰਥਨ ਕੀਤਾ ਅਤੇ ਸਮਾਂ-ਸਾਰਣੀ ਵਿੱਚ ਸੁਧਾਰ ਮੰਗਿਆ।"), true, "CERTAIN", ["F1", "F2"]), candidate("II", t("The association considered the entire bus service a failure.", "संघ ने पूरी बस सेवा को विफल माना।", "ਸੰਘ ਨੇ ਪੂਰੀ ਬੱਸ ਸੇਵਾ ਨੂੰ ਅਸਫਲ ਮੰਨਿਆ।"), false, "UNSUPPORTED_OR_CONTRADICTED", ["F1", "F2"], "STRONGER_CLAIM")], explanation: t("Welcoming the service shows support, while the request shows a limited scheduling concern. It does not amount to rejecting the service. Therefore, only I follows.", "सेवा का स्वागत समर्थन दिखाता है, जबकि अनुरोध केवल समय-सारणी में सुधार से जुड़ा है। इससे पूरी सेवा को असफल मानना सिद्ध नहीं होता। इसलिए केवल I सही है।", "ਸੇਵਾ ਦਾ ਸਵਾਗਤ ਸਮਰਥਨ ਦੱਸਦਾ ਹੈ, ਜਦਕਿ ਬੇਨਤੀ ਸਿਰਫ਼ ਸਮਾਂ-ਸਾਰਣੀ ਦੇ ਸੁਧਾਰ ਨਾਲ ਜੁੜੀ ਹੈ। ਇਸ ਤੋਂ ਪੂਰੀ ਸੇਵਾ ਨੂੰ ਅਸਫਲ ਮੰਨਣਾ ਸਾਬਤ ਨਹੀਂ ਹੁੰਦਾ। ਇਸ ਲਈ ਕੇਵਲ I ਸਹੀ ਹੈ।") }),
  scenario({ id: "SIF-CP016-ADVANCED", cpId: "SIF-CP016", difficulty: "HARD", domain: "BUSINESS", mechanisms: ["ADVANCED_PARAGRAPH", "MULTIPLE_FACTOR", "SCOPE_CONTROL"], statement: t("A retailer introduced home delivery at three of its twelve branches in April. Orders at those three branches rose by 14% in May, while orders at the remaining branches were almost unchanged. The retailer has not yet decided whether to extend the service.", "एक विक्रेता ने अप्रैल में अपनी बारह शाखाओं में से तीन पर होम डिलीवरी शुरू की। मई में इन तीन शाखाओं के ऑर्डर 14% बढ़े, जबकि बाकी शाखाओं के ऑर्डर लगभग अपरिवर्तित रहे। विक्रेता ने अभी सेवा बढ़ाने का निर्णय नहीं लिया है।", "ਇੱਕ ਵਿਕਰੇਤਾ ਨੇ ਅਪ੍ਰੈਲ ਵਿੱਚ ਆਪਣੀਆਂ ਬਾਰਾਂ ਸ਼ਾਖਾਵਾਂ ਵਿੱਚੋਂ ਤਿੰਨ 'ਤੇ ਘਰ ਡਿਲਿਵਰੀ ਸ਼ੁਰੂ ਕੀਤੀ। ਮਈ ਵਿੱਚ ਇਨ੍ਹਾਂ ਤਿੰਨ ਸ਼ਾਖਾਵਾਂ ਦੇ ਆਰਡਰ 14% ਵਧੇ, ਜਦਕਿ ਬਾਕੀ ਸ਼ਾਖਾਵਾਂ ਦੇ ਆਰਡਰ ਲਗਭਗ ਬਦਲੇ ਨਹੀਂ। ਵਿਕਰੇਤਾ ਨੇ ਹਾਲੇ ਸੇਵਾ ਵਧਾਉਣ ਦਾ ਫ਼ੈਸਲਾ ਨਹੀਂ ਕੀਤਾ।"), facts: [fact("F1", t("Delivery began at three branches.", "डिलीवरी तीन शाखाओं में शुरू हुई।", "ਡਿਲਿਵਰੀ ਤਿੰਨ ਸ਼ਾਖਾਵਾਂ ਵਿੱਚ ਸ਼ੁਰੂ ਹੋਈ।")), fact("F2", t("Their orders rose 14%.", "उनके ऑर्डर 14% बढ़े।", "ਉਨ੍ਹਾਂ ਦੇ ਆਰਡਰ 14% ਵਧੇ।")), fact("F3", t("Other branches were almost unchanged.", "बाकी शाखाएं लगभग अपरिवर्तित रहीं।", "ਬਾਕੀ ਸ਼ਾਖਾਵਾਂ ਲਗਭਗ ਬਦਲੀਆਂ ਨਹੀਂ।")), fact("F4", t("No expansion decision has been made.", "विस्तार का निर्णय नहीं हुआ।", "ਵਿਸਥਾਰ ਦਾ ਫ਼ੈਸਲਾ ਨਹੀਂ ਹੋਇਆ।"))], candidates: [candidate("I", t("In May, order growth was concentrated at the branches where home delivery had been introduced.", "मई में ऑर्डर वृद्धि मुख्यतः उन्हीं शाखाओं में हुई जहां होम डिलीवरी शुरू की गई थी।", "ਮਈ ਵਿੱਚ ਆਰਡਰ ਵਾਧਾ ਮੁੱਖ ਤੌਰ 'ਤੇ ਉਨ੍ਹਾਂ ਸ਼ਾਖਾਵਾਂ ਵਿੱਚ ਹੋਇਆ ਜਿੱਥੇ ਘਰ ਡਿਲਿਵਰੀ ਸ਼ੁਰੂ ਕੀਤੀ ਗਈ ਸੀ।"), true, "CERTAIN", ["F1", "F2", "F3"]), candidate("II", t("The retailer will certainly introduce home delivery at all branches.", "विक्रेता निश्चित रूप से सभी शाखाओं में होम डिलीवरी शुरू करेगा।", "ਵਿਕਰੇਤਾ ਯਕੀਨੀ ਤੌਰ 'ਤੇ ਸਾਰੀਆਂ ਸ਼ਾਖਾਵਾਂ ਵਿੱਚ ਘਰ ਡਿਲਿਵਰੀ ਸ਼ੁਰੂ ਕਰੇਗਾ।"), false, "UNSUPPORTED_OR_CONTRADICTED", ["F4"], "EXCESSIVE_CERTAINTY")], explanation: t("The reported growth occurred at the three delivery branches while other branches were almost unchanged, so I follows. The passage expressly says that no expansion decision has been made, so II does not follow.", "वृद्धि उन्हीं तीन शाखाओं में हुई जहां डिलीवरी शुरू हुई, जबकि बाकी शाखाएं लगभग अपरिवर्तित रहीं; इसलिए I सही है। विस्तार का निर्णय अभी नहीं हुआ, इसलिए II सही नहीं है।", "ਵਾਧਾ ਉਨ੍ਹਾਂ ਤਿੰਨ ਸ਼ਾਖਾਵਾਂ ਵਿੱਚ ਹੋਇਆ ਜਿੱਥੇ ਡਿਲਿਵਰੀ ਸ਼ੁਰੂ ਹੋਈ, ਜਦਕਿ ਬਾਕੀ ਸ਼ਾਖਾਵਾਂ ਲਗਭਗ ਬਦਲੀਆਂ ਨਹੀਂ; ਇਸ ਲਈ I ਸਹੀ ਹੈ। ਵਿਸਥਾਰ ਦਾ ਫ਼ੈਸਲਾ ਹਾਲੇ ਨਹੀਂ ਹੋਇਆ, ਇਸ ਲਈ II ਸਹੀ ਨਹੀਂ ਹੈ।") }),
  scenario({ id: "SIF-CP017-MIXED", cpId: "SIF-CP017", difficulty: "HARD", domain: "BANKING", mechanisms: ["MIXED", "QUANTIFIER", "CONDITIONAL_DIRECTION", "SCOPE_CONTROL"], statement: t("Only verified customers could join the pilot service. Some verified customers at two selected branches joined it, and 72% of those participants used the service more than once.", "केवल सत्यापित ग्राहक पायलट सेवा में शामिल हो सकते थे। दो चयनित शाखाओं के कुछ सत्यापित ग्राहक इसमें शामिल हुए और उन प्रतिभागियों में से 72% ने सेवा का एक से अधिक बार उपयोग किया।", "ਕੇਵਲ ਤਸਦੀਕਸ਼ੁਦਾ ਗਾਹਕ ਪਾਇਲਟ ਸੇਵਾ ਵਿੱਚ ਸ਼ਾਮਲ ਹੋ ਸਕਦੇ ਸਨ। ਦੋ ਚੁਣੀਆਂ ਸ਼ਾਖਾਵਾਂ ਦੇ ਕੁਝ ਤਸਦੀਕਸ਼ੁਦਾ ਗਾਹਕ ਇਸ ਵਿੱਚ ਸ਼ਾਮਲ ਹੋਏ ਅਤੇ ਉਨ੍ਹਾਂ ਭਾਗੀਦਾਰਾਂ ਵਿੱਚੋਂ 72% ਨੇ ਸੇਵਾ ਇੱਕ ਤੋਂ ਵੱਧ ਵਾਰ ਵਰਤੀ।"), facts: [fact("F1", t("Verification was necessary to join.", "शामिल होने के लिए सत्यापन आवश्यक था।", "ਸ਼ਾਮਲ ਹੋਣ ਲਈ ਤਸਦੀਕ ਲਾਜ਼ਮੀ ਸੀ।")), fact("F2", t("Some verified customers at two branches joined.", "दो शाखाओं के कुछ सत्यापित ग्राहक शामिल हुए।", "ਦੋ ਸ਼ਾਖਾਵਾਂ ਦੇ ਕੁਝ ਤਸਦੀਕਸ਼ੁਦਾ ਗਾਹਕ ਸ਼ਾਮਲ ਹੋਏ।")), fact("F3", t("72% of participants used it more than once.", "72% प्रतिभागियों ने एक से अधिक बार उपयोग किया।", "72% ਭਾਗੀਦਾਰਾਂ ਨੇ ਇੱਕ ਤੋਂ ਵੱਧ ਵਾਰ ਵਰਤਿਆ।"))], candidates: [candidate("I", t("Every participant in the pilot was a verified customer.", "पायलट सेवा का हर प्रतिभागी सत्यापित ग्राहक था।", "ਪਾਇਲਟ ਸੇਵਾ ਦਾ ਹਰ ਭਾਗੀਦਾਰ ਤਸਦੀਕਸ਼ੁਦਾ ਗਾਹਕ ਸੀ।"), true, "CERTAIN", ["F1"]), candidate("II", t("Most verified customers of the bank used the service more than once.", "बैंक के अधिकांश सत्यापित ग्राहकों ने सेवा का एक से अधिक बार उपयोग किया।", "ਬੈਂਕ ਦੇ ਜ਼ਿਆਦਾਤਰ ਤਸਦੀਕਸ਼ੁਦਾ ਗਾਹਕਾਂ ਨੇ ਸੇਵਾ ਇੱਕ ਤੋਂ ਵੱਧ ਵਾਰ ਵਰਤੀ।"), false, "UNSUPPORTED_OR_CONTRADICTED", ["F2", "F3"], "SCOPE_CHANGE")], explanation: t("The word ‘only’ makes verification necessary for every participant, so I follows. The 72% figure applies only to pilot participants at two branches, not to all verified bank customers. Therefore, II does not follow.", "‘केवल’ सत्यापन को हर प्रतिभागी के लिए आवश्यक बनाता है, इसलिए I सही है। 72% का आंकड़ा केवल दो शाखाओं के पायलट प्रतिभागियों पर लागू है, सभी सत्यापित ग्राहकों पर नहीं। इसलिए II सही नहीं है।", "‘ਕੇਵਲ’ ਤਸਦੀਕ ਨੂੰ ਹਰ ਭਾਗੀਦਾਰ ਲਈ ਲਾਜ਼ਮੀ ਬਣਾਉਂਦਾ ਹੈ, ਇਸ ਲਈ I ਸਹੀ ਹੈ। 72% ਦਾ ਅੰਕੜਾ ਸਿਰਫ਼ ਦੋ ਸ਼ਾਖਾਵਾਂ ਦੇ ਪਾਇਲਟ ਭਾਗੀਦਾਰਾਂ ਲਈ ਹੈ, ਸਾਰੇ ਤਸਦੀਕਸ਼ੁਦਾ ਗਾਹਕਾਂ ਲਈ ਨਹੀਂ। ਇਸ ਲਈ II ਸਹੀ ਨਹੀਂ ਹੈ।") }),
];


const cp012To014Authorities: readonly SifScenarioAuthority[] = [
  scenario({ id:"SIF-CP012-SURVEY-SAMPLE", cpId:"SIF-CP012", difficulty:"MEDIUM", domain:"SURVEY", mechanisms:["SUPPORT_THRESHOLD"], statement:t("A poll of 240 library members found that 156 preferred evening hours. The poll used an online form. It does not report how non-responding members would have answered.","पुस्तकालय के 240 सदस्यों के सर्वेक्षण में 156 ने शाम का समय पसंद किया। सर्वेक्षण ऑनलाइन फॉर्म से हुआ। उत्तर न देने वाले सदस्य क्या कहते, इसकी जानकारी नहीं दी गई।","ਲਾਇਬ੍ਰੇਰੀ ਦੇ 240 ਮੈਂਬਰਾਂ ਦੇ ਸਰਵੇਖਣ ਵਿੱਚ 156 ਨੇ ਸ਼ਾਮ ਦਾ ਸਮਾਂ ਪਸੰਦ ਕੀਤਾ। ਸਰਵੇਖਣ ਆਨਲਾਈਨ ਫਾਰਮ ਰਾਹੀਂ ਹੋਇਆ। ਜਵਾਬ ਨਾ ਦੇਣ ਵਾਲੇ ਮੈਂਬਰ ਕੀ ਕਹਿੰਦੇ, ਇਸ ਦੀ ਜਾਣਕਾਰੀ ਨਹੀਂ ਦਿੱਤੀ ਗਈ।"), facts:[fact("F1",t("156 of 240 respondents preferred evening hours.","240 ਵਿੱਚੋਂ 156 ਜਵਾਬਦਾਤਾਵਾਂ ਨੇ ਸ਼ਾਮ ਦਾ ਸਮਾਂ ਪਸੰਦ ਕੀਤਾ।","240 ਵਿੱਚੋਂ 156 ਜਵਾਬਦਾਤਾਵਾਂ ਨੇ ਸ਼ਾਮ ਦਾ ਸਮਾਂ ਪਸੰਦ ਕੀਤਾ।"))], candidates:[candidate("I",t("A majority of the respondents preferred evening hours.","उत्तरदाताओं के बहुमत ने शाम का समय पसंद किया।","ਜਵਾਬਦਾਤਾਵਾਂ ਦੇ ਬਹੁਮਤ ਨੇ ਸ਼ਾਮ ਦਾ ਸਮਾਂ ਪਸੰਦ ਕੀਤਾ।"),true,"CERTAIN",["F1"]),candidate("II",t("Most library members prefer evening hours.","पुस्तकालय के अधिकांश सदस्य शाम का समय पसंद करते हैं।","ਲਾਇਬ੍ਰੇਰੀ ਦੇ ਬਹੁਤੇ ਮੈਂਬਰ ਸ਼ਾਮ ਦਾ ਸਮਾਂ ਪਸੰਦ ਕਰਦੇ ਹਨ।"),false,"POSSIBLE_ONLY",["F1"],"SCOPE_CHANGE")], explanation:t("The count supports a majority among respondents. It does not establish what every library member prefers, especially those who did not respond. Only I follows.","गिनती उत्तरदाताओं में बहुमत का समर्थन करती है। इससे सभी सदस्यों, खासकर उत्तर न देने वालों, की पसंद सिद्ध नहीं होती। केवल I सही है।","ਗਿਣਤੀ ਜਵਾਬਦਾਤਾਵਾਂ ਵਿੱਚ ਬਹੁਮਤ ਦਾ ਸਮਰਥਨ ਕਰਦੀ ਹੈ। ਇਸ ਨਾਲ ਸਾਰੇ ਮੈਂਬਰਾਂ, ਖ਼ਾਸ ਕਰਕੇ ਜਵਾਬ ਨਾ ਦੇਣ ਵਾਲਿਆਂ, ਦੀ ਪਸੰਦ ਸਾਬਤ ਨਹੀਂ ਹੁੰਦੀ। ਕੇਵਲ I ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP012-CLINIC-TRIAL", cpId:"SIF-CP012", difficulty:"HARD", domain:"HEALTHCARE", mechanisms:["SUPPORT_THRESHOLD"], statement:t("In a clinic trial, 42 of 60 participants reported less pain after using a new gel for one week. The report gives no comparison group. It does not say whether the improvement lasted.","क्लिनिक के परीक्षण में 60 में से 42 प्रतिभागियों ने एक सप्ताह नया जेल लगाने के बाद दर्द कम होने की बात कही। रिपोर्ट में तुलना के लिए कोई समूह नहीं है। यह भी नहीं बताया गया कि सुधार कितने समय तक रहा।","ਕਲੀਨਿਕ ਦੇ ਅਜ਼ਮਾਇਸ਼ ਵਿੱਚ 60 ਵਿੱਚੋਂ 42 ਭਾਗੀਦਾਰਾਂ ਨੇ ਇੱਕ ਹਫ਼ਤਾ ਨਵੀਂ ਜੈਲ ਲਗਾਉਣ ਤੋਂ ਬਾਅਦ ਦਰਦ ਘੱਟ ਹੋਣ ਦੀ ਗੱਲ ਕਹੀ। ਰਿਪੋਰਟ ਵਿੱਚ ਤੁਲਨਾ ਲਈ ਕੋਈ ਸਮੂਹ ਨਹੀਂ ਹੈ। ਇਹ ਵੀ ਨਹੀਂ ਦੱਸਿਆ ਕਿ ਸੁਧਾਰ ਕਿੰਨਾ ਸਮਾਂ ਰਿਹਾ।"), facts:[fact("F1",t("42 of 60 participants reported less pain after one week.","60 में से 42 प्रतिभागियों ने एक सप्ताह बाद दर्द कम बताया।","60 ਵਿੱਚੋਂ 42 ਭਾਗੀਦਾਰਾਂ ਨੇ ਇੱਕ ਹਫ਼ਤੇ ਬਾਅਦ ਦਰਦ ਘੱਟ ਦੱਸਿਆ।"))], candidates:[candidate("II",t("A majority of the participants reported less pain after one week.","अधिकांश प्रतिभागियों ने एक सप्ताह बाद दर्द कम बताया।","ਬਹੁਤੇ ਭਾਗੀਦਾਰਾਂ ਨੇ ਇੱਕ ਹਫ਼ਤੇ ਬਾਅਦ ਦਰਦ ਘੱਟ ਦੱਸਿਆ।"),true,"CERTAIN",["F1"]),candidate("I",t("The gel caused a lasting reduction in pain.","जेल से दर्द में स्थायी कमी आई।","ਜੈਲ ਨਾਲ ਦਰਦ ਵਿੱਚ ਪੱਕੀ ਕਮੀ ਆਈ।"),false,"POSSIBLE_ONLY",["F1"],"CAUSE_ASSUMPTION")], explanation:t("The responses support a majority report of short-term improvement. Without a comparison group or follow-up, the gel's cause and lasting effect are not established. Only II follows.","उत्तर अल्पकालिक सुधार बताने वाले बहुमत का समर्थन करते हैं। तुलना समूह और बाद की जानकारी के बिना जेल का कारणात्मक या स्थायी असर सिद्ध नहीं है। केवल II सही है।","ਜਵਾਬ ਥੋੜ੍ਹੇ ਸਮੇਂ ਦੇ ਸੁਧਾਰ ਦੱਸਣ ਵਾਲੇ ਬਹੁਮਤ ਦਾ ਸਮਰਥਨ ਕਰਦੇ ਹਨ। ਤੁਲਨਾ ਸਮੂਹ ਅਤੇ ਬਾਅਦ ਦੀ ਜਾਣਕਾਰੀ ਤੋਂ ਬਿਨਾਂ ਜੈਲ ਦਾ ਕਾਰਣਕ ਜਾਂ ਪੱਕਾ ਅਸਰ ਸਾਬਤ ਨਹੀਂ ਹੁੰਦਾ। ਕੇਵਲ II ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP012-BANK-QUEUE", cpId:"SIF-CP012", difficulty:"MEDIUM", domain:"BANKING", mechanisms:["SUPPORT_THRESHOLD"], statement:t("The bank received 85 address-change requests on Monday. Forty were verified by the end of that day. The remaining requests were still under review.","बैंक को सोमवार को पते में बदलाव के 85 अनुरोध मिले। दिन के अंत तक 40 का सत्यापन हुआ। बाकी अनुरोध जाँच में थे।","ਬੈਂਕ ਨੂੰ ਸੋਮਵਾਰ ਨੂੰ ਪਤਾ ਬਦਲਣ ਦੀਆਂ 85 ਬੇਨਤੀਆਂ ਮਿਲੀਆਂ। ਦਿਨ ਦੇ ਅੰਤ ਤੱਕ 40 ਦੀ ਤਸਦੀਕ ਹੋਈ। ਬਾਕੀ ਬੇਨਤੀਆਂ ਜਾਂਚ ਅਧੀਨ ਸਨ।"), facts:[fact("F1",t("Forty of 85 requests were verified that day.","85 में से 40 अनुरोध उसी दिन सत्यापित हुए।","85 ਵਿੱਚੋਂ 40 ਬੇਨਤੀਆਂ ਉਸੇ ਦਿਨ ਤਸਦੀਕ ਹੋਈਆਂ।"))], candidates:[candidate("II",t("Fewer than half of the requests were verified on Monday.","सोमवार को आधे से कम अनुरोध सत्यापित हुए।","ਸੋਮਵਾਰ ਨੂੰ ਅੱਧੀਆਂ ਤੋਂ ਘੱਟ ਬੇਨਤੀਆਂ ਤਸਦੀਕ ਹੋਈਆਂ।"),true,"CERTAIN",["F1"]),candidate("I",t("The bank's verification process is generally slow.","बैंक की सत्यापन प्रक्रिया आम तौर पर धीमी है।","ਬੈਂਕ ਦੀ ਤਸਦੀਕ ਪ੍ਰਕਿਰਿਆ ਆਮ ਤੌਰ 'ਤੇ ਹੌਲੀ ਹੈ।"),false,"POSSIBLE_ONLY",["F1"],"UNSUPPORTED_DETAIL")], explanation:t("Forty is fewer than half of 85, so I follows. A single day's queue does not establish that the process is generally slow. Only II follows.","40, 85 के आधे से कम है, इसलिए I सही है। एक दिन की लंबित सूची से प्रक्रिया के आम तौर पर धीमे होने का निष्कर्ष नहीं निकलता। केवल II सही है।","40, 85 ਦੇ ਅੱਧ ਤੋਂ ਘੱਟ ਹੈ, ਇਸ ਲਈ I ਸਹੀ ਹੈ। ਇੱਕ ਦਿਨ ਦੀ ਬਕਾਇਆ ਸੂਚੀ ਤੋਂ ਪ੍ਰਕਿਰਿਆ ਦੇ ਆਮ ਤੌਰ 'ਤੇ ਹੌਲੀ ਹੋਣ ਦਾ ਨਤੀਜਾ ਨਹੀਂ ਨਿਕਲਦਾ। ਕੇਵਲ II ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP013-TRIAL-STORES", cpId:"SIF-CP013", difficulty:"MEDIUM", domain:"BUSINESS", mechanisms:["SCOPE_CONTROL"], statement:t("A retailer tested self-checkout counters in two of its 30 stores for one month. Both test stores recorded shorter average queues during that month. The report includes no other stores or months.","एक खुदरा कंपनी ने अपने 30 में से दो स्टोर में एक महीने तक स्वयं-चेकआउट काउंटर आजमाए। उस महीने दोनों स्टोर में औसत कतारें छोटी रहीं। रिपोर्ट में अन्य स्टोर या महीने शामिल नहीं हैं।","ਇੱਕ ਰਿਟੇਲ ਕੰਪਨੀ ਨੇ ਆਪਣੇ 30 ਵਿੱਚੋਂ ਦੋ ਸਟੋਰਾਂ ਵਿੱਚ ਇੱਕ ਮਹੀਨੇ ਲਈ ਸਵੈ-ਚੈੱਕਆਉਟ ਕਾਊਂਟਰ ਅਜ਼ਮਾਏ। ਉਸ ਮਹੀਨੇ ਦੋਵੇਂ ਸਟੋਰਾਂ ਵਿੱਚ ਔਸਤ ਕਤਾਰਾਂ ਛੋਟੀਆਂ ਰਹੀਆਂ। ਰਿਪੋਰਟ ਵਿੱਚ ਹੋਰ ਸਟੋਰ ਜਾਂ ਮਹੀਨੇ ਸ਼ਾਮਲ ਨਹੀਂ ਹਨ।"), facts:[fact("F1",t("Both trial stores had shorter average queues during that month.","उस महीने दोनों परीक्षण स्टोर में औसत कतारें छोटी थीं।","ਉਸ ਮਹੀਨੇ ਦੋਵੇਂ ਅਜ਼ਮਾਇਸ਼ੀ ਸਟੋਰਾਂ ਵਿੱਚ ਔਸਤ ਕਤਾਰਾਂ ਛੋਟੀਆਂ ਸਨ।"))], candidates:[candidate("I",t("The two test stores recorded shorter average queues during the trial month.","परीक्षण के महीने में दोनों स्टोर की औसत कतारें छोटी रहीं।","ਅਜ਼ਮਾਇਸ਼ ਦੇ ਮਹੀਨੇ ਦੋਵੇਂ ਸਟੋਰਾਂ ਦੀਆਂ ਔਸਤ ਕਤਾਰਾਂ ਛੋਟੀਆਂ ਰਹੀਆਂ।"),true,"CERTAIN",["F1"]),candidate("II",t("Self-checkout reduced queues throughout the retailer's chain.","स्वयं-चेकआउट से कंपनी की पूरी शृंखला में कतारें कम हुईं।","ਸਵੈ-ਚੈੱਕਆਉਟ ਨਾਲ ਕੰਪਨੀ ਦੀ ਪੂਰੀ ਲੜੀ ਵਿੱਚ ਕਤਾਰਾਂ ਘੱਟ ਹੋਈਆਂ।"),false,"UNSUPPORTED_OR_CONTRADICTED",["F1"],"SCOPE_CHANGE")], explanation:t("The result applies to two stores for one month. It cannot establish the same result at the other 28 stores or in later months. Only I follows.","नतीजा दो स्टोर और एक महीने तक सीमित है। इससे बाकी 28 स्टोर या आगे के महीनों के बारे में वही बात सिद्ध नहीं होती। केवल I सही है।","ਨਤੀਜਾ ਦੋ ਸਟੋਰਾਂ ਅਤੇ ਇੱਕ ਮਹੀਨੇ ਤੱਕ ਸੀਮਿਤ ਹੈ। ਇਸ ਨਾਲ ਬਾਕੀ 28 ਸਟੋਰਾਂ ਜਾਂ ਅਗਲੇ ਮਹੀਨਿਆਂ ਲਈ ਉਹੀ ਗੱਲ ਸਾਬਤ ਨਹੀਂ ਹੁੰਦੀ। ਕੇਵਲ I ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP013-ONE-WARD", cpId:"SIF-CP013", difficulty:"HARD", domain:"PUBLIC_ADMINISTRATION", mechanisms:["SCOPE_CONTROL"], statement:t("After heavy rain, potholes were reported on three roads in North Ward. The municipal team inspected those roads the next morning. No figures are given for other wards.","तेज बारिश के बाद उत्तर वार्ड की तीन सड़कों पर गड्ढों की शिकायत मिली। नगर निगम की टीम ने अगली सुबह उन्हीं सड़कों का निरीक्षण किया। दूसरे वार्डों के आंकड़े नहीं दिए गए।","ਤੇਜ਼ ਮੀਂਹ ਤੋਂ ਬਾਅਦ ਉੱਤਰੀ ਵਾਰਡ ਦੀਆਂ ਤਿੰਨ ਸੜਕਾਂ 'ਤੇ ਖੱਡਿਆਂ ਦੀਆਂ ਸ਼ਿਕਾਇਤਾਂ ਮਿਲੀਆਂ। ਨਗਰ ਨਿਗਮ ਦੀ ਟੀਮ ਨੇ ਅਗਲੀ ਸਵੇਰ ਉਨ੍ਹਾਂ ਸੜਕਾਂ ਦੀ ਜਾਂਚ ਕੀਤੀ। ਹੋਰ ਵਾਰਡਾਂ ਦੇ ਅੰਕੜੇ ਨਹੀਂ ਦਿੱਤੇ ਗਏ।"), facts:[fact("F1",t("Three reported roads in North Ward were inspected.","उत्तर वार्ड की शिकायत वाली तीन सड़कों का निरीक्षण हुआ।","ਉੱਤਰੀ ਵਾਰਡ ਦੀਆਂ ਸ਼ਿਕਾਇਤ ਵਾਲੀਆਂ ਤਿੰਨ ਸੜਕਾਂ ਦੀ ਜਾਂਚ ਹੋਈ।"))], candidates:[candidate("II",t("The team inspected the three reported roads in North Ward.","टीम ने उत्तर वार्ड की बताई गई तीन सड़कों का निरीक्षण किया।","ਟੀਮ ਨੇ ਉੱਤਰੀ ਵਾਰਡ ਦੀਆਂ ਦੱਸੀਆਂ ਤਿੰਨ ਸੜਕਾਂ ਦੀ ਜਾਂਚ ਕੀਤੀ।"),true,"CERTAIN",["F1"]),candidate("I",t("Heavy rain damaged roads throughout the municipality.","तेज बारिश से पूरे नगर निगम क्षेत्र की सड़कें क्षतिग्रस्त हुईं।","ਤੇਜ਼ ਮੀਂਹ ਨਾਲ ਪੂਰੇ ਨਗਰ ਨਿਗਮ ਖੇਤਰ ਦੀਆਂ ਸੜਕਾਂ ਨੁਕਸਾਨੀਆਂ ਗਈਆਂ।"),false,"POSSIBLE_ONLY",["F1"],"OVERGENERALISATION")], explanation:t("The report identifies three roads in one ward. It gives no evidence about every road in the municipality. Only II follows.","रिपोर्ट एक वार्ड की तीन सड़कों के बारे में है। इससे नगर निगम क्षेत्र की हर सड़क के बारे में निष्कर्ष नहीं निकलता। केवल II सही है।","ਰਿਪੋਰਟ ਇੱਕ ਵਾਰਡ ਦੀਆਂ ਤਿੰਨ ਸੜਕਾਂ ਬਾਰੇ ਹੈ। ਇਸ ਤੋਂ ਨਗਰ ਨਿਗਮ ਖੇਤਰ ਦੀ ਹਰ ਸੜਕ ਬਾਰੇ ਨਤੀਜਾ ਨਹੀਂ ਨਿਕਲਦਾ। ਕੇਵਲ II ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP013-NIGHT-SHIFT", cpId:"SIF-CP013", difficulty:"MEDIUM", domain:"WORKPLACE", mechanisms:["SCOPE_CONTROL"], statement:t("On Friday's night shift, two of five packing lines stopped for maintenance. The other three continued operating. The log covers that shift only.","शुक्रवार की रात की पाली में पाँच में से दो पैकिंग लाइनें रखरखाव के लिए रुकीं। बाकी तीन चलती रहीं। लॉग केवल उसी पाली का है।","ਸ਼ੁੱਕਰਵਾਰ ਦੀ ਰਾਤ ਦੀ ਸ਼ਿਫਟ ਵਿੱਚ ਪੰਜ ਵਿੱਚੋਂ ਦੋ ਪੈਕਿੰਗ ਲਾਈਨਾਂ ਰੱਖ-ਰਖਾਅ ਲਈ ਰੁਕੀਆਂ। ਬਾਕੀ ਤਿੰਨ ਚੱਲਦੀਆਂ ਰਹੀਆਂ। ਰਿਕਾਰਡ ਸਿਰਫ਼ ਉਸੇ ਸ਼ਿਫਟ ਦਾ ਹੈ।"), facts:[fact("F1",t("Three lines continued operating during the stated shift.","बताई गई पाली में तीन लाइनें चलती रहीं।","ਦੱਸੀ ਸ਼ਿਫਟ ਵਿੱਚ ਤਿੰਨ ਲਾਈਨਾਂ ਚੱਲਦੀਆਂ ਰਹੀਆਂ।"))], candidates:[candidate("II",t("Some packing lines operated during Friday's night shift.","शुक्रवार की रात की पाली में कुछ पैकिंग लाइनें चलीं।","ਸ਼ੁੱਕਰਵਾਰ ਦੀ ਰਾਤ ਦੀ ਸ਼ਿਫਟ ਵਿੱਚ ਕੁਝ ਪੈਕਿੰਗ ਲਾਈਨਾਂ ਚੱਲੀਆਂ।"),true,"CERTAIN",["F1"]),candidate("I",t("Packing lines are usually unavailable at night.","पैकिंग लाइनें आम तौर पर रात में बंद रहती हैं।","ਪੈਕਿੰਗ ਲਾਈਨਾਂ ਆਮ ਤੌਰ 'ਤੇ ਰਾਤ ਨੂੰ ਬੰਦ ਰਹਿੰਦੀਆਂ ਹਨ।"),false,"POSSIBLE_ONLY",["F1"],"TIME_DISTORTION")], explanation:t("The log says three lines ran during this shift. It does not describe the usual night schedule. Only II follows.","लॉग के अनुसार इस पाली में तीन लाइनें चलीं। इससे रात की सामान्य समय-सारणी का पता नहीं चलता। केवल II सही है।","ਰਿਕਾਰਡ ਅਨੁਸਾਰ ਇਸ ਸ਼ਿਫਟ ਵਿੱਚ ਤਿੰਨ ਲਾਈਨਾਂ ਚੱਲੀਆਂ। ਇਸ ਨਾਲ ਰਾਤ ਦੀ ਆਮ ਸਮਾਂ-ਸਾਰਣੀ ਦਾ ਪਤਾ ਨਹੀਂ ਲੱਗਦਾ। ਕੇਵਲ II ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP014-LICENCE-STEPS", cpId:"SIF-CP014", difficulty:"MEDIUM", domain:"PUBLIC_ADMINISTRATION", mechanisms:["TIME_SEQUENCE"], statement:t("Nisha filed her licence application on 3 May. The office checked her documents on 8 May. Her practical-test appointment was booked on 10 May.","निशा ने 3 मई को लाइसेंस का आवेदन जमा किया। कार्यालय ने 8 मई को उसके दस्तावेज़ जाँचे। व्यावहारिक परीक्षा की तारीख 10 मई को तय हुई।","ਨਿਸ਼ਾ ਨੇ 3 ਮਈ ਨੂੰ ਲਾਇਸੈਂਸ ਦੀ ਅਰਜ਼ੀ ਦਿੱਤੀ। ਦਫ਼ਤਰ ਨੇ 8 ਮਈ ਨੂੰ ਉਸ ਦੇ ਦਸਤਾਵੇਜ਼ ਜਾਂਚੇ। ਪ੍ਰੈਕਟੀਕਲ ਟੈਸਟ ਦੀ ਮਿਤੀ 10 ਮਈ ਨੂੰ ਤੈਅ ਹੋਈ।"), facts:[fact("F1",t("Document check followed filing and preceded the test appointment.","दस्तावेज़ जाँच आवेदन के बाद और परीक्षा की तारीख से पहले हुई।","ਦਸਤਾਵੇਜ਼ ਜਾਂਚ ਅਰਜ਼ੀ ਤੋਂ ਬਾਅਦ ਅਤੇ ਟੈਸਟ ਦੀ ਮਿਤੀ ਤੋਂ ਪਹਿਲਾਂ ਹੋਈ।"))], candidates:[candidate("I",t("The document check occurred after filing and before the test appointment.","दस्तावेज़ जाँच आवेदन के बाद और परीक्षा की तारीख से पहले हुई।","ਦਸਤਾਵੇਜ਼ ਜਾਂਚ ਅਰਜ਼ੀ ਤੋਂ ਬਾਅਦ ਅਤੇ ਟੈਸਟ ਦੀ ਮਿਤੀ ਤੋਂ ਪਹਿਲਾਂ ਹੋਈ।"),true,"CERTAIN",["F1"]),candidate("II",t("The document check resulted in approval of Nisha's licence.","दस्तावेज़ जाँच के बाद निशा का लाइसेंस मंजूर हुआ।","ਦਸਤਾਵੇਜ਼ ਜਾਂਚ ਤੋਂ ਬਾਅਦ ਨਿਸ਼ਾ ਦਾ ਲਾਇਸੈਂਸ ਮਨਜ਼ੂਰ ਹੋਇਆ।"),false,"POSSIBLE_ONLY",["F1"],"CAUSE_ASSUMPTION")], explanation:t("The dates place the check between filing and the test appointment. They do not state that the licence was approved. Only I follows.","तिथियाँ जाँच को आवेदन और परीक्षा की तारीख के बीच रखती हैं। लाइसेंस मंजूर होने की बात नहीं कही गई। केवल I सही है।","ਤਾਰੀਖਾਂ ਜਾਂਚ ਨੂੰ ਅਰਜ਼ੀ ਅਤੇ ਟੈਸਟ ਦੀ ਮਿਤੀ ਦੇ ਵਿਚਕਾਰ ਰੱਖਦੀਆਂ ਹਨ। ਲਾਇਸੈਂਸ ਮਨਜ਼ੂਰ ਹੋਣ ਦੀ ਗੱਲ ਨਹੀਂ ਦੱਸੀ ਗਈ। ਕੇਵਲ I ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP014-TRAIN-DEPARTURES", cpId:"SIF-CP014", difficulty:"MEDIUM", domain:"TRANSPORT", mechanisms:["TIME_SEQUENCE"], statement:t("Train 1 left the station at 6:10 a.m. Train 2 left at 6:25 a.m. The signal log records both departures.","ट्रेन 1 सुबह 6:10 बजे स्टेशन से रवाना हुई। ट्रेन 2 सुबह 6:25 बजे रवाना हुई। सिग्नल लॉग में दोनों प्रस्थान दर्ज हैं।","ਰੇਲਗੱਡੀ 1 ਸਵੇਰੇ 6:10 ਵਜੇ ਸਟੇਸ਼ਨ ਤੋਂ ਚੱਲੀ। ਰੇਲਗੱਡੀ 2 ਸਵੇਰੇ 6:25 ਵਜੇ ਚੱਲੀ। ਸਿਗਨਲ ਰਿਕਾਰਡ ਵਿੱਚ ਦੋਵੇਂ ਰਵਾਨਗੀਆਂ ਦਰਜ ਹਨ।"), facts:[fact("F1",t("Train 2 left 15 minutes after Train 1.","ट्रेन 2, ट्रेन 1 के 15 मिनट बाद रवाना हुई।","ਰੇਲਗੱਡੀ 2, ਰੇਲਗੱਡੀ 1 ਤੋਂ 15 ਮਿੰਟ ਬਾਅਦ ਚੱਲੀ।"))], candidates:[candidate("II",t("Train 2 departed 15 minutes after Train 1.","ट्रेन 2, ट्रेन 1 के 15 मिनट बाद रवाना हुई।","ਰੇਲਗੱਡੀ 2, ਰੇਲਗੱਡੀ 1 ਤੋਂ 15 ਮਿੰਟ ਬਾਅਦ ਚੱਲੀ।"),true,"CERTAIN",["F1"]),candidate("I",t("Train 1's departure caused a delay to Train 2.","ट्रेन 1 के प्रस्थान से ट्रेन 2 को देरी हुई।","ਰੇਲਗੱਡੀ 1 ਦੇ ਚੱਲਣ ਕਾਰਨ ਰੇਲਗੱਡੀ 2 ਨੂੰ ਦੇਰੀ ਹੋਈ।"),false,"POSSIBLE_ONLY",["F1"],"CAUSE_ASSUMPTION")], explanation:t("The times establish a 15-minute gap. They do not say that Train 1 caused a delay to Train 2. Only II follows.","समय में 15 मिनट का अंतर है। यह नहीं बताया गया कि ट्रेन 1 के कारण ट्रेन 2 को देरी हुई। केवल II सही है।","ਸਮੇਂ ਵਿੱਚ 15 ਮਿੰਟ ਦਾ ਫ਼ਰਕ ਹੈ। ਇਹ ਨਹੀਂ ਦੱਸਿਆ ਗਿਆ ਕਿ ਰੇਲਗੱਡੀ 1 ਕਾਰਨ ਰੇਲਗੱਡੀ 2 ਨੂੰ ਦੇਰੀ ਹੋਈ। ਕੇਵਲ II ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP014-PARTS-DELIVERY", cpId:"SIF-CP014", difficulty:"MEDIUM", domain:"BUSINESS", mechanisms:["TIME_SEQUENCE"], statement:t("A supplier dispatched parts on 12 June. The warehouse recorded their arrival on 14 June. Assembly using those parts began on 16 June.","आपूर्तिकर्ता ने 12 जून को पुर्जे भेजे। गोदाम ने 14 जून को उनके पहुंचने का रिकॉर्ड बनाया। उन पुर्जों से असेंबली 16 जून को शुरू हुई।","ਸਪਲਾਇਰ ਨੇ 12 ਜੂਨ ਨੂੰ ਪੁਰਜ਼ੇ ਭੇਜੇ। ਗੋਦਾਮ ਨੇ 14 ਜੂਨ ਨੂੰ ਉਨ੍ਹਾਂ ਦੇ ਪਹੁੰਚਣ ਦੀ ਦਰਜ ਕੀਤੀ। ਉਨ੍ਹਾਂ ਪੁਰਜ਼ਿਆਂ ਨਾਲ ਅਸੈਂਬਲੀ 16 ਜੂਨ ਨੂੰ ਸ਼ੁਰੂ ਹੋਈ।"), facts:[fact("F1",t("The parts arrived before assembly began.","असेंबली शुरू होने से पहले पुर्जे पहुंच गए।","ਅਸੈਂਬਲੀ ਸ਼ੁਰੂ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਪੁਰਜ਼ੇ ਪਹੁੰਚ ਗਏ।"))], candidates:[candidate("II",t("The parts arrived before they were used in assembly.","असेंबली में इस्तेमाल से पहले पुर्जे पहुंच गए।","ਅਸੈਂਬਲੀ ਵਿੱਚ ਵਰਤੋਂ ਤੋਂ ਪਹਿਲਾਂ ਪੁਰਜ਼ੇ ਪਹੁੰਚ ਗਏ।"),true,"CERTAIN",["F1"]),candidate("I",t("The arrival date delayed the assembly schedule.","पुर्जे देर से पहुंचने के कारण असेंबली का कार्यक्रम बिगड़ा।","ਪੁਰਜ਼ੇ ਦੇਰ ਨਾਲ ਪਹੁੰਚਣ ਕਰਕੇ ਅਸੈਂਬਲੀ ਦਾ ਸਮਾਂ ਬਦਲਿਆ।"),false,"POSSIBLE_ONLY",["F1"],"CAUSE_ASSUMPTION")], explanation:t("The records show that the parts arrived before assembly began. No planned arrival date or delay is given, so II does not follow. Only II follows.","रिकॉर्ड बताते हैं कि असेंबली शुरू होने से पहले पुर्जे पहुंच गए। तय तारीख या देरी का उल्लेख नहीं है, इसलिए II सही नहीं है। केवल II सही है।","ਰਿਕਾਰਡ ਦੱਸਦੇ ਹਨ ਕਿ ਅਸੈਂਬਲੀ ਸ਼ੁਰੂ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਪੁਰਜ਼ੇ ਪਹੁੰਚ ਗਏ। ਨਿਰਧਾਰਤ ਮਿਤੀ ਜਾਂ ਦੇਰੀ ਦਾ ਜ਼ਿਕਰ ਨਹੀਂ ਹੈ, ਇਸ ਲਈ II ਸਹੀ ਨਹੀਂ ਹੈ। ਕੇਵਲ II ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP012-RAIL-REFUND", cpId:"SIF-CP012", difficulty:"MEDIUM", domain:"TRANSPORT", mechanisms:["SUPPORT_THRESHOLD"], statement:t("A rail operator cancelled one morning service because of a signal fault. Passengers on that service were offered a refund or another train. The notice does not say how many passengers chose either option.","सिग्नल की खराबी के कारण रेल संचालक ने सुबह की एक सेवा रद्द की। उस सेवा के यात्रियों को किराया वापसी या दूसरी ट्रेन का विकल्प दिया गया। सूचना में यह नहीं बताया गया कि कितने यात्रियों ने कौन-सा विकल्प चुना।","ਸਿਗਨਲ ਦੀ ਖ਼ਰਾਬੀ ਕਾਰਨ ਰੇਲਵੇ ਨੇ ਸਵੇਰ ਦੀ ਇੱਕ ਸੇਵਾ ਰੱਦ ਕੀਤੀ। ਉਸ ਸੇਵਾ ਦੇ ਯਾਤਰੀਆਂ ਨੂੰ ਕਿਰਾਇਆ ਵਾਪਸੀ ਜਾਂ ਹੋਰ ਰੇਲਗੱਡੀ ਦਾ ਵਿਕਲਪ ਦਿੱਤਾ ਗਿਆ। ਸੂਚਨਾ ਵਿੱਚ ਨਹੀਂ ਦੱਸਿਆ ਕਿ ਕਿੰਨੇ ਯਾਤਰੀਆਂ ਨੇ ਕਿਹੜਾ ਵਿਕਲਪ ਚੁਣਿਆ।"), facts:[fact("F1",t("Passengers were offered a refund or another train after the service was cancelled.","सेवा रद्द होने के बाद यात्रियों को किराया वापसी या दूसरी ट्रेन का विकल्प मिला।","ਸੇਵਾ ਰੱਦ ਹੋਣ ਤੋਂ ਬਾਅਦ ਯਾਤਰੀਆਂ ਨੂੰ ਕਿਰਾਇਆ ਵਾਪਸੀ ਜਾਂ ਹੋਰ ਰੇਲਗੱਡੀ ਦਾ ਵਿਕਲਪ ਮਿਲਿਆ।"))], candidates:[candidate("II",t("Every affected passenger chose the refund.","हर प्रभावित यात्री ने किराया वापसी चुनी।","ਹਰ ਪ੍ਰਭਾਵਿਤ ਯਾਤਰੀ ਨੇ ਕਿਰਾਇਆ ਵਾਪਸੀ ਚੁਣੀ।"),false,"POSSIBLE_ONLY",["F1"],"UNSUPPORTED_DETAIL"),candidate("I",t("Passengers were offered one of two alternatives after the cancellation.","ਰੱਦ ਹੋਣ ਤੋਂ ਬਾਅਦ ਯਾਤਰੀਆਂ ਨੂੰ ਦੋ ਵਿੱਚੋਂ ਇੱਕ ਵਿਕਲਪ ਦਿੱਤਾ ਗਿਆ।","ਰੱਦ ਹੋਣ ਤੋਂ ਬਾਅਦ ਯਾਤਰੀਆਂ ਨੂੰ ਦੋ ਵਿੱਚੋਂ ਇੱਕ ਵਿਕਲਪ ਦਿੱਤਾ ਗਿਆ।"),true,"CERTAIN",["F1"])], explanation:t("The notice confirms that both alternatives were offered, but gives no passenger choices. Therefore, II follows and I is not established.","सूचना दोनों विकल्प दिए जाने की पुष्टि करती है, पर यात्रियों की पसंद नहीं बताती। इसलिए II सही है, जबकि I सिद्ध नहीं है।","ਸੂਚਨਾ ਦੋਵੇਂ ਵਿਕਲਪ ਦਿੱਤੇ ਜਾਣ ਦੀ ਪੁਸ਼ਟੀ ਕਰਦੀ ਹੈ, ਪਰ ਯਾਤਰੀਆਂ ਦੀ ਚੋਣ ਨਹੀਂ ਦੱਸਦੀ। ਇਸ ਲਈ II ਸਹੀ ਹੈ, ਪਰ I ਸਾਬਤ ਨਹੀਂ ਹੁੰਦਾ।") }),
  scenario({ id:"SIF-CP012-ACCOUNT-ALERT", cpId:"SIF-CP012", difficulty:"HARD", domain:"BANKING", mechanisms:["SUPPORT_THRESHOLD"], statement:t("A bank sent a security alert after three online transactions were made on an account within ten minutes. The account holder confirmed only the first transaction. The bank's notice does not identify who made the other two.","एक खाते से दस मिनट में तीन ऑनलाइन लेनदेन होने पर बैंक ने सुरक्षा सूचना भेजी। खाताधारक ने केवल पहले लेनदेन की पुष्टि की। बैंक की सूचना में यह नहीं बताया गया कि बाकी दो लेनदेन किसने किए।","ਇੱਕ ਖਾਤੇ ਵਿੱਚ ਦਸ ਮਿੰਟਾਂ ਅੰਦਰ ਤਿੰਨ ਆਨਲਾਈਨ ਲੈਣ-ਦੇਣ ਹੋਣ 'ਤੇ ਬੈਂਕ ਨੇ ਸੁਰੱਖਿਆ ਸੁਨੇਹਾ ਭੇਜਿਆ। ਖਾਤਾਧਾਰਕ ਨੇ ਸਿਰਫ਼ ਪਹਿਲੇ ਲੈਣ-ਦੇਣ ਦੀ ਪੁਸ਼ਟੀ ਕੀਤੀ। ਬੈਂਕ ਦੀ ਸੂਚਨਾ ਵਿੱਚ ਨਹੀਂ ਦੱਸਿਆ ਕਿ ਬਾਕੀ ਦੋ ਲੈਣ-ਦੇਣ ਕਿਸ ਨੇ ਕੀਤੇ।"), facts:[fact("F1",t("The account holder confirmed the first transaction but not the other two.","खाताधारक ने पहले लेनदेन की पुष्टि की, बाकी दो की नहीं।","ਖਾਤਾਧਾਰਕ ਨੇ ਪਹਿਲੇ ਲੈਣ-ਦੇਣ ਦੀ ਪੁਸ਼ਟੀ ਕੀਤੀ, ਬਾਕੀ ਦੋ ਦੀ ਨਹੀਂ।"))], candidates:[candidate("I",t("The account holder made all three transactions.","खाताधारक ने तीनों लेनदेन किए।","ਖਾਤਾਧਾਰਕ ਨੇ ਤਿੰਨੇ ਲੈਣ-ਦੇਣ ਕੀਤੇ।"),false,"POSSIBLE_ONLY",["F1"],"UNSUPPORTED_DETAIL"),candidate("II",t("The account holder confirmed only one of the three transactions.","खाताधारक ने तीन में से केवल एक लेनदेन की पुष्टि की।","ਖਾਤਾਧਾਰਕ ਨੇ ਤਿੰਨ ਵਿੱਚੋਂ ਸਿਰਫ਼ ਇੱਕ ਲੈਣ-ਦੇਣ ਦੀ ਪੁਸ਼ਟੀ ਕੀਤੀ।"),true,"CERTAIN",["F1"])], explanation:t("Only the first transaction was confirmed by the account holder. The notice does not establish who made the remaining two, so I goes beyond the evidence.","खाताधारक ने केवल पहले लेनदेन की पुष्टि की। सूचना से बाकी दो लेनदेन करने वाले का पता नहीं चलता, इसलिए I दिए गए प्रमाण से आगे जाता है।","ਖਾਤਾਧਾਰਕ ਨੇ ਸਿਰਫ਼ ਪਹਿਲੇ ਲੈਣ-ਦੇਣ ਦੀ ਪੁਸ਼ਟੀ ਕੀਤੀ। ਸੂਚਨਾ ਤੋਂ ਬਾਕੀ ਦੋ ਲੈਣ-ਦੇਣ ਕਰਨ ਵਾਲੇ ਦਾ ਪਤਾ ਨਹੀਂ ਲੱਗਦਾ, ਇਸ ਲਈ I ਦਿੱਤੇ ਸਬੂਤ ਤੋਂ ਅੱਗੇ ਜਾਂਦਾ ਹੈ।") }),
  scenario({ id:"SIF-CP012-FACTORY-NOISE", cpId:"SIF-CP012", difficulty:"MEDIUM", domain:"WORKPLACE", mechanisms:["SUPPORT_THRESHOLD"], statement:t("Noise readings at one factory workstation exceeded the prescribed limit during the 2 p.m. check. The safety officer asked the manager to repeat the measurement. No reading from the repeat check is provided.","दोपहर 2 बजे की जाँच में कारखाने के एक कार्य-स्थल पर शोर का स्तर तय सीमा से अधिक था। सुरक्षा अधिकारी ने प्रबंधक से दोबारा माप लेने को कहा। दोबारा जाँच का परिणाम नहीं दिया गया।","ਦੁਪਹਿਰ 2 ਵਜੇ ਦੀ ਜਾਂਚ ਵਿੱਚ ਫੈਕਟਰੀ ਦੇ ਇੱਕ ਕੰਮ ਵਾਲੇ ਸਥਾਨ 'ਤੇ ਸ਼ੋਰ ਨਿਰਧਾਰਤ ਹੱਦ ਤੋਂ ਵੱਧ ਸੀ। ਸੁਰੱਖਿਆ ਅਧਿਕਾਰੀ ਨੇ ਪ੍ਰਬੰਧਕ ਨੂੰ ਮੁੜ ਮਾਪ ਲੈਣ ਲਈ ਕਿਹਾ। ਦੂਜੀ ਜਾਂਚ ਦਾ ਨਤੀਜਾ ਨਹੀਂ ਦਿੱਤਾ ਗਿਆ।"), facts:[fact("F1",t("The reading at one workstation exceeded the limit during the 2 p.m. check.","ਦੁਪਹਿਰ 2 ਵਜੇ ਦੀ ਜਾਂਚ ਵਿੱਚ ਇੱਕ ਥਾਂ ਦਾ ਮਾਪ ਹੱਦ ਤੋਂ ਵੱਧ ਸੀ।","ਦੁਪਹਿਰ 2 ਵਜੇ ਦੀ ਜਾਂਚ ਵਿੱਚ ਇੱਕ ਥਾਂ ਦਾ ਮਾਪ ਹੱਦ ਤੋਂ ਵੱਧ ਸੀ।"))], candidates:[candidate("I",t("The factory's noise level is always above the prescribed limit.","कारखाने में शोर का स्तर हमेशा तय सीमा से अधिक रहता है।","ਫੈਕਟਰੀ ਵਿੱਚ ਸ਼ੋਰ ਦਾ ਪੱਧਰ ਹਮੇਸ਼ਾ ਨਿਰਧਾਰਤ ਹੱਦ ਤੋਂ ਵੱਧ ਰਹਿੰਦਾ ਹੈ।"),false,"POSSIBLE_ONLY",["F1"],"EXCESSIVE_CERTAINTY"),candidate("II",t("At least one reading at that workstation was above the limit during the check.","जाँच के समय उस कार्य-स्थल का कम-से-कम एक माप सीमा से अधिक था।","ਜਾਂਚ ਵੇਲੇ ਉਸ ਕੰਮ ਵਾਲੀ ਥਾਂ ਦਾ ਘੱਟੋ-ਘੱਟ ਇੱਕ ਮਾਪ ਹੱਦ ਤੋਂ ਵੱਧ ਸੀ।"),true,"CERTAIN",["F1"])], explanation:t("The report gives one above-limit reading at one time and place. It does not establish a constant condition throughout the factory. Therefore, only II follows.","रिपोर्ट एक समय और एक जगह का सीमा से अधिक माप देती है। इससे पूरे कारखाने की स्थायी स्थिति सिद्ध नहीं होती। इसलिए केवल II सही है।","ਰਿਪੋਰਟ ਇੱਕ ਸਮੇਂ ਅਤੇ ਇੱਕ ਥਾਂ ਦਾ ਹੱਦ ਤੋਂ ਵੱਧ ਮਾਪ ਦਿੰਦੀ ਹੈ। ਇਸ ਨਾਲ ਪੂਰੀ ਫੈਕਟਰੀ ਦੀ ਸਥਾਈ ਹਾਲਤ ਸਾਬਤ ਨਹੀਂ ਹੁੰਦੀ। ਇਸ ਲਈ ਕੇਵਲ II ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP012-MEDICINE-STOCK", cpId:"SIF-CP012", difficulty:"HARD", domain:"HEALTHCARE", mechanisms:["SUPPORT_THRESHOLD"], statement:t("A clinic had enough doses of a vaccine for 40 people on Monday morning. By noon, 31 people had been vaccinated. The stock register does not show whether the remaining doses were reserved or later used.","सोमवार सुबह क्लिनिक में 40 लोगों के लिए टीके की खुराकें थीं। दोपहर तक 31 लोगों को टीका लगाया गया। स्टॉक रजिस्टर यह नहीं बताता कि बची खुराकें आरक्षित थीं या बाद में इस्तेमाल हुईं।","ਸੋਮਵਾਰ ਸਵੇਰੇ ਕਲੀਨਿਕ ਕੋਲ 40 ਲੋਕਾਂ ਲਈ ਟੀਕੇ ਦੀਆਂ ਖੁਰਾਕਾਂ ਸਨ। ਦੁਪਹਿਰ ਤੱਕ 31 ਲੋਕਾਂ ਨੂੰ ਟੀਕਾ ਲੱਗਿਆ। ਸਟਾਕ ਰਜਿਸਟਰ ਨਹੀਂ ਦੱਸਦਾ ਕਿ ਬਾਕੀ ਖੁਰਾਕਾਂ ਰਾਖਵੀਆਂ ਸਨ ਜਾਂ ਬਾਅਦ ਵਿੱਚ ਵਰਤੀਆਂ ਗਈਆਂ।"), facts:[fact("F1",t("Thirty-one people had received the vaccine by noon Monday.","सोमवार दोपहर तक 31 लोगों को टीका लगाया जा चुका था।","ਸੋਮਵਾਰ ਦੁਪਹਿਰ ਤੱਕ 31 ਲੋਕਾਂ ਨੂੰ ਟੀਕਾ ਲੱਗ ਚੁੱਕਾ ਸੀ।"))], candidates:[candidate("II",t("Nine doses remained unused at noon.","दोपहर तक नौ खुराकें इस्तेमाल नहीं हुई थीं।","ਦੁਪਹਿਰ ਤੱਕ ਨੌਂ ਖੁਰਾਕਾਂ ਵਰਤੀਆਂ ਨਹੀਂ ਗਈਆਂ ਸਨ।"),false,"POSSIBLE_ONLY",["F1"],"UNSUPPORTED_DETAIL"),candidate("I",t("At least 31 people had been vaccinated by noon Monday.","सोमवार दोपहर तक कम-से-कम 31 लोगों को टीका लगाया गया था।","ਸੋਮਵਾਰ ਦੁਪਹਿਰ ਤੱਕ ਘੱਟੋ-ਘੱਟ 31 ਲੋਕਾਂ ਨੂੰ ਟੀਕਾ ਲੱਗ ਚੁੱਕਾ ਸੀ।"),true,"CERTAIN",["F1"])], explanation:t("The register confirms 31 vaccinations by noon. The initial stock does not prove that exactly nine doses remained unused, since the later stock position is not stated. Therefore, only II follows.","रजिस्टर दोपहर तक 31 टीकाकरण की पुष्टि करता है। शुरुआती स्टॉक से यह सिद्ध नहीं होता कि ठीक नौ खुराकें बचीं, क्योंकि बाद का स्टॉक नहीं बताया गया। इसलिए केवल II सही है।","ਰਜਿਸਟਰ ਦੁਪਹਿਰ ਤੱਕ 31 ਟੀਕਿਆਂ ਦੀ ਪੁਸ਼ਟੀ ਕਰਦਾ ਹੈ। ਸ਼ੁਰੂਆਤੀ ਸਟਾਕ ਨਾਲ ਇਹ ਸਾਬਤ ਨਹੀਂ ਹੁੰਦਾ ਕਿ ਠੀਕ ਨੌਂ ਖੁਰਾਕਾਂ ਬਚੀਆਂ, ਕਿਉਂਕਿ ਬਾਅਦ ਦਾ ਸਟਾਕ ਨਹੀਂ ਦੱਸਿਆ। ਇਸ ਲਈ ਕੇਵਲ II ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP013-REGIONAL-TRAINING", cpId:"SIF-CP013", difficulty:"MEDIUM", domain:"EDUCATION", mechanisms:["SCOPE_CONTROL"], statement:t("A training centre offered a computer course at its two rural branches during the spring term. Both branches enrolled learners. The notice does not describe the centre's urban branches or other terms.","वसंत सत्र में एक प्रशिक्षण केंद्र ने अपनी दो ग्रामीण शाखाओं में कंप्यूटर पाठ्यक्रम चलाया। दोनों शाखाओं में विद्यार्थियों ने दाखिला लिया। सूचना में केंद्र की शहरी शाखाओं या अन्य सत्रों का विवरण नहीं है।","ਬਸੰਤ ਸੈਸ਼ਨ ਵਿੱਚ ਇੱਕ ਸਿਖਲਾਈ ਕੇਂਦਰ ਨੇ ਆਪਣੀਆਂ ਦੋ ਪੇਂਡੂ ਸ਼ਾਖਾਵਾਂ ਵਿੱਚ ਕੰਪਿਊਟਰ ਕੋਰਸ ਚਲਾਇਆ। ਦੋਵੇਂ ਸ਼ਾਖਾਵਾਂ ਵਿੱਚ ਵਿਦਿਆਰਥੀਆਂ ਨੇ ਦਾਖ਼ਲਾ ਲਿਆ। ਸੂਚਨਾ ਵਿੱਚ ਕੇਂਦਰ ਦੀਆਂ ਸ਼ਹਿਰੀ ਸ਼ਾਖਾਵਾਂ ਜਾਂ ਹੋਰ ਸੈਸ਼ਨਾਂ ਦਾ ਵੇਰਵਾ ਨਹੀਂ ਹੈ।"), facts:[fact("F1",t("Learners enrolled at both rural branches during the spring term.","वसंत सत्र में दोनों ग्रामीण शाखाओं में विद्यार्थियों ने दाखिला लिया।","ਬਸੰਤ ਸੈਸ਼ਨ ਵਿੱਚ ਦੋਵੇਂ ਪੇਂਡੂ ਸ਼ਾਖਾਵਾਂ ਵਿੱਚ ਵਿਦਿਆਰਥੀਆਂ ਨੇ ਦਾਖ਼ਲਾ ਲਿਆ।"))], candidates:[candidate("II",t("The course attracted learners at both rural branches in the spring term.","वसंत सत्र में दोनों ग्रामीण शाखाओं में विद्यार्थियों ने पाठ्यक्रम लिया।","ਬਸੰਤ ਸੈਸ਼ਨ ਵਿੱਚ ਦੋਵੇਂ ਪੇਂਡੂ ਸ਼ਾਖਾਵਾਂ ਵਿੱਚ ਵਿਦਿਆਰਥੀਆਂ ਨੇ ਕੋਰਸ ਲਿਆ।"),true,"CERTAIN",["F1"]),candidate("I",t("Learners enrolled at every branch in every term.","हर सत्र में हर शाखा पर विद्यार्थियों ने दाखिला लिया।","ਹਰ ਸੈਸ਼ਨ ਵਿੱਚ ਹਰ ਸ਼ਾਖਾ 'ਤੇ ਵਿਦਿਆਰਥੀਆਂ ਨੇ ਦਾਖ਼ਲਾ ਲਿਆ।"),false,"POSSIBLE_ONLY",["F1"],"SCOPE_CHANGE")], explanation:t("The notice confirms enrolment at two rural branches in one term. It says nothing about the other branches or terms, so II overextends the result. Only II follows.","सूचना एक सत्र में दो ग्रामीण शाखाओं के दाखिले की पुष्टि करती है। अन्य शाखाओं या सत्रों की जानकारी नहीं है, इसलिए II दायरे से आगे जाता है। केवल II सही है।","ਸੂਚਨਾ ਇੱਕ ਸੈਸ਼ਨ ਵਿੱਚ ਦੋ ਪੇਂਡੂ ਸ਼ਾਖਾਵਾਂ ਦੇ ਦਾਖ਼ਲੇ ਦੀ ਪੁਸ਼ਟੀ ਕਰਦੀ ਹੈ। ਹੋਰ ਸ਼ਾਖਾਵਾਂ ਜਾਂ ਸੈਸ਼ਨਾਂ ਦੀ ਜਾਣਕਾਰੀ ਨਹੀਂ, ਇਸ ਲਈ II ਦਾਇਰੇ ਤੋਂ ਅੱਗੇ ਜਾਂਦਾ ਹੈ। ਕੇਵਲ II ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP013-ONE-MARKET", cpId:"SIF-CP013", difficulty:"HARD", domain:"BUSINESS", mechanisms:["SCOPE_CONTROL"], statement:t("A price survey at the central market found that onions cost less on Tuesday than on Monday. The survey covered five stalls. It gives no prices from other markets or later days.","मुख्य बाजार के मूल्य सर्वेक्षण में मंगलवार को प्याज की कीमत सोमवार से कम थी। सर्वेक्षण में पाँच दुकानों को शामिल किया गया। अन्य बाजारों या अगले दिनों के भाव नहीं दिए गए।","ਮੁੱਖ ਬਾਜ਼ਾਰ ਦੇ ਭਾਅ ਸਰਵੇਖਣ ਵਿੱਚ ਮੰਗਲਵਾਰ ਨੂੰ ਪਿਆਜ਼ ਦੀ ਕੀਮਤ ਸੋਮਵਾਰ ਨਾਲੋਂ ਘੱਟ ਸੀ। ਸਰਵੇਖਣ ਵਿੱਚ ਪੰਜ ਦੁਕਾਨਾਂ ਸ਼ਾਮਲ ਸਨ। ਹੋਰ ਬਾਜ਼ਾਰਾਂ ਜਾਂ ਅਗਲੇ ਦਿਨਾਂ ਦੇ ਭਾਅ ਨਹੀਂ ਦਿੱਤੇ ਗਏ।"), facts:[fact("F1",t("At five central-market stalls, onions cost less on Tuesday than Monday.","ਮੁੱਖ ਬਾਜ਼ਾਰ ਦੀਆਂ ਪੰਜ ਦੁਕਾਨਾਂ 'ਤੇ ਮੰਗਲਵਾਰ ਨੂੰ ਪਿਆਜ਼ ਸੋਮਵਾਰ ਨਾਲੋਂ ਸਸਤਾ ਸੀ।","ਮੁੱਖ ਬਾਜ਼ਾਰ ਦੀਆਂ ਪੰਜ ਦੁਕਾਨਾਂ 'ਤੇ ਮੰਗਲਵਾਰ ਨੂੰ ਪਿਆਜ਼ ਸੋਮਵਾਰ ਨਾਲੋਂ ਸਸਤਾ ਸੀ।"))], candidates:[candidate("I",t("Onions became cheaper at those five stalls on Tuesday than on Monday.","उन पाँच दुकानों पर मंगलवार को प्याज सोमवार से सस्ता हुआ।","ਉਨ੍ਹਾਂ ਪੰਜ ਦੁਕਾਨਾਂ 'ਤੇ ਮੰਗਲਵਾਰ ਨੂੰ ਪਿਆਜ਼ ਸੋਮਵਾਰ ਨਾਲੋਂ ਸਸਤਾ ਸੀ।"),true,"CERTAIN",["F1"]),candidate("II",t("Onions were cheaper across all markets on Tuesday.","मंगलवार को सभी बाजारों में प्याज सस्ता था।","ਮੰਗਲਵਾਰ ਨੂੰ ਸਾਰੇ ਬਾਜ਼ਾਰਾਂ ਵਿੱਚ ਪਿਆਜ਼ ਸਸਤਾ ਸੀ।"),false,"UNSUPPORTED_OR_CONTRADICTED",["F1"],"OVERGENERALISATION")], explanation:t("The comparison applies to five stalls in one market on two days. It does not establish prices in all markets. Only I follows.","तुलना एक बाजार की पाँच दुकानों और दो दिनों की है। इससे सभी बाजारों के भाव सिद्ध नहीं होते। केवल I सही है।","ਤੁਲਨਾ ਇੱਕ ਬਾਜ਼ਾਰ ਦੀਆਂ ਪੰਜ ਦੁਕਾਨਾਂ ਅਤੇ ਦੋ ਦਿਨਾਂ ਦੀ ਹੈ। ਇਸ ਨਾਲ ਸਾਰੇ ਬਾਜ਼ਾਰਾਂ ਦੇ ਭਾਅ ਸਾਬਤ ਨਹੀਂ ਹੁੰਦੇ। ਕੇਵਲ I ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP013-LOCAL-REPAIR", cpId:"SIF-CP013", difficulty:"MEDIUM", domain:"PUBLIC_ADMINISTRATION", mechanisms:["SCOPE_CONTROL"], statement:t("The municipal team repaired three streetlights on Lake Road on 6 November. The job card lists the parts used. It does not report the condition of lights on other roads.","नगर निगम की टीम ने 6 नवंबर को लेक रोड की तीन स्ट्रीटलाइटें ठीक कीं। कार्य-पर्ची में इस्तेमाल किए गए पुर्जों का विवरण है। दूसरी सड़कों की लाइटों की स्थिति नहीं बताई गई।","ਨਗਰ ਨਿਗਮ ਦੀ ਟੀਮ ਨੇ 6 ਨਵੰਬਰ ਨੂੰ ਲੇਕ ਰੋਡ ਦੀਆਂ ਤਿੰਨ ਸਟ੍ਰੀਟ ਲਾਈਟਾਂ ਠੀਕ ਕੀਤੀਆਂ। ਕੰਮ ਦੀ ਪਰਚੀ ਵਿੱਚ ਵਰਤੇ ਪੁਰਜ਼ਿਆਂ ਦਾ ਵੇਰਵਾ ਹੈ। ਹੋਰ ਸੜਕਾਂ ਦੀਆਂ ਲਾਈਟਾਂ ਦੀ ਹਾਲਤ ਨਹੀਂ ਦੱਸੀ ਗਈ।"), facts:[fact("F1",t("Three streetlights on Lake Road were repaired on 6 November.","6 नवंबर को लेक रोड की तीन स्ट्रीटलाइटें ठीक हुईं।","6 ਨਵੰਬਰ ਨੂੰ ਲੇਕ ਰੋਡ ਦੀਆਂ ਤਿੰਨ ਸਟ੍ਰੀਟ ਲਾਈਟਾਂ ਠੀਕ ਹੋਈਆਂ।"))], candidates:[candidate("II",t("The municipal team repaired three lights on Lake Road that day.","उस दिन नगर निगम की टीम ने लेक रोड की तीन लाइटें ठीक कीं।","ਉਸ ਦਿਨ ਨਗਰ ਨਿਗਮ ਦੀ ਟੀਮ ਨੇ ਲੇਕ ਰੋਡ ਦੀਆਂ ਤਿੰਨ ਲਾਈਟਾਂ ਠੀਕ ਕੀਤੀਆਂ।"),true,"CERTAIN",["F1"]),candidate("I",t("Streetlights across the municipality were out of order.","नगर निगम क्षेत्र की सभी स्ट्रीटलाइटें खराब थीं।","ਨਗਰ ਨਿਗਮ ਖੇਤਰ ਦੀਆਂ ਸਾਰੀਆਂ ਸਟ੍ਰੀਟ ਲਾਈਟਾਂ ਖ਼ਰਾਬ ਸਨ।"),false,"POSSIBLE_ONLY",["F1"],"SCOPE_CHANGE")], explanation:t("The job card covers three lights on one road on one date. It does not describe the rest of the municipality. Only II follows.","कार्य-पर्ची एक तारीख पर एक सड़क की तीन लाइटों तक सीमित है। नगर निगम क्षेत्र की बाकी लाइटों की जानकारी नहीं है। केवल II सही है।","ਕੰਮ ਦੀ ਪਰਚੀ ਇੱਕ ਮਿਤੀ 'ਤੇ ਇੱਕ ਸੜਕ ਦੀਆਂ ਤਿੰਨ ਲਾਈਟਾਂ ਤੱਕ ਸੀਮਿਤ ਹੈ। ਨਗਰ ਨਿਗਮ ਖੇਤਰ ਦੀਆਂ ਬਾਕੀ ਲਾਈਟਾਂ ਬਾਰੇ ਜਾਣਕਾਰੀ ਨਹੀਂ ਹੈ। ਕੇਵਲ II ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP013-STAFF-SURVEY", cpId:"SIF-CP013", difficulty:"HARD", domain:"WORKPLACE", mechanisms:["SCOPE_CONTROL"], statement:t("A staff survey at the head office received replies from 74 employees in the accounts unit. Forty-nine favoured a four-day training schedule. The survey did not include other units or offices.","मुख्य कार्यालय में लेखा इकाई के 74 कर्मचारियों ने सर्वेक्षण का उत्तर दिया। 49 ने चार दिन के प्रशिक्षण कार्यक्रम का समर्थन किया। सर्वेक्षण में अन्य इकाइयों या कार्यालयों को शामिल नहीं किया गया।","ਮੁੱਖ ਦਫ਼ਤਰ ਦੀ ਲੇਖਾ ਇਕਾਈ ਦੇ 74 ਕਰਮਚਾਰੀਆਂ ਨੇ ਸਰਵੇਖਣ ਦਾ ਜਵਾਬ ਦਿੱਤਾ। 49 ਨੇ ਚਾਰ ਦਿਨਾਂ ਦੇ ਸਿਖਲਾਈ ਕਾਰਜਕ੍ਰਮ ਦਾ ਸਮਰਥਨ ਕੀਤਾ। ਹੋਰ ਇਕਾਈਆਂ ਜਾਂ ਦਫ਼ਤਰਾਂ ਨੂੰ ਸਰਵੇਖਣ ਵਿੱਚ ਸ਼ਾਮਲ ਨਹੀਂ ਕੀਤਾ ਗਿਆ।"), facts:[fact("F1",t("Forty-nine of 74 responding accounts-unit staff at the head office favoured the schedule.","मुख्य कार्यालय की लेखा इकाई के 74 उत्तरदाताओं में से 49 ने कार्यक्रम का समर्थन किया।","ਮੁੱਖ ਦਫ਼ਤਰ ਦੀ ਲੇਖਾ ਇਕਾਈ ਦੇ 74 ਜਵਾਬਦਾਤਾਵਾਂ ਵਿੱਚੋਂ 49 ਨੇ ਕਾਰਜਕ੍ਰਮ ਦਾ ਸਮਰਥਨ ਕੀਤਾ।"))], candidates:[candidate("I",t("A majority of responding accounts-unit staff at the head office favoured the schedule.","मुख्य कार्यालय की लेखा इकाई के उत्तरदाताओं के बहुमत ने कार्यक्रम का समर्थन किया।","ਮੁੱਖ ਦਫ਼ਤਰ ਦੀ ਲੇਖਾ ਇਕਾਈ ਦੇ ਜਵਾਬਦਾਤਾਵਾਂ ਦੇ ਬਹੁਮਤ ਨੇ ਕਾਰਜਕ੍ਰਮ ਦਾ ਸਮਰਥਨ ਕੀਤਾ।"),true,"CERTAIN",["F1"]),candidate("II",t("Most employees across the organisation favour the schedule.","पूरे संगठन के अधिकांश कर्मचारी इस कार्यक्रम का समर्थन करते हैं।","ਪੂਰੇ ਸੰਗਠਨ ਦੇ ਬਹੁਤੇ ਕਰਮਚਾਰੀ ਇਸ ਕਾਰਜਕ੍ਰਮ ਦਾ ਸਮਰਥਨ ਕਰਦੇ ਹਨ।"),false,"UNSUPPORTED_OR_CONTRADICTED",["F1"],"OVERGENERALISATION")], explanation:t("The majority is among respondents from one unit at one office. Other employees were not surveyed, so the organisation-wide claim is unsupported. Only I follows.","बहुमत एक कार्यालय की एक इकाई के उत्तरदाताओं में है। अन्य कर्मचारियों का सर्वेक्षण नहीं हुआ, इसलिए पूरे संगठन का दावा सिद्ध नहीं है। केवल I सही है।","ਬਹੁਮਤ ਇੱਕ ਦਫ਼ਤਰ ਦੀ ਇੱਕ ਇਕਾਈ ਦੇ ਜਵਾਬਦਾਤਾਵਾਂ ਵਿੱਚ ਹੈ। ਹੋਰ ਕਰਮਚਾਰੀਆਂ ਦਾ ਸਰਵੇਖਣ ਨਹੀਂ ਹੋਇਆ, ਇਸ ਲਈ ਪੂਰੇ ਸੰਗਠਨ ਦਾ ਦਾਅਵਾ ਸਾਬਤ ਨਹੀਂ। ਕੇਵਲ I ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP014-APPLICATION-REVIEW", cpId:"SIF-CP014", difficulty:"MEDIUM", domain:"BANKING", mechanisms:["TIME_SEQUENCE"], statement:t("A customer submitted a loan application on 7 July. The branch verified the address on 9 July. The credit team requested an income document on 12 July.","ग्राहक ने 7 जुलाई को ऋण आवेदन जमा किया। शाखा ने 9 जुलाई को पते का सत्यापन किया। ऋण दल ने 12 जुलाई को आय का दस्तावेज़ मांगा।","ਗਾਹਕ ਨੇ 7 ਜੁਲਾਈ ਨੂੰ ਕਰਜ਼ੇ ਦੀ ਅਰਜ਼ੀ ਦਿੱਤੀ। ਸ਼ਾਖਾ ਨੇ 9 ਜੁਲਾਈ ਨੂੰ ਪਤੇ ਦੀ ਤਸਦੀਕ ਕੀਤੀ। ਕਰੈਡਿਟ ਟੀਮ ਨੇ 12 ਜੁਲਾਈ ਨੂੰ ਆਮਦਨ ਦਾ ਦਸਤਾਵੇਜ਼ ਮੰਗਿਆ।"), facts:[fact("F1",t("The address check followed the application and preceded the income-document request.","पते की जाँच आवेदन के बाद और आय-दस्तावेज़ की माँग से पहले हुई।","ਪਤੇ ਦੀ ਜਾਂਚ ਅਰਜ਼ੀ ਤੋਂ ਬਾਅਦ ਅਤੇ ਆਮਦਨ ਦਸਤਾਵੇਜ਼ ਦੀ ਮੰਗ ਤੋਂ ਪਹਿਲਾਂ ਹੋਈ।"))], candidates:[candidate("II",t("The branch verified the address before the credit team requested the income document.","ऋण दल द्वारा आय का दस्तावेज़ माँगने से पहले शाखा ने पते का सत्यापन किया।","ਕਰੈਡਿਟ ਟੀਮ ਵੱਲੋਂ ਆਮਦਨ ਦਾ ਦਸਤਾਵੇਜ਼ ਮੰਗਣ ਤੋਂ ਪਹਿਲਾਂ ਸ਼ਾਖਾ ਨੇ ਪਤੇ ਦੀ ਤਸਦੀਕ ਕੀਤੀ।"),true,"CERTAIN",["F1"]),candidate("I",t("The address verification led to the request for an income document.","पते के सत्यापन के कारण आय का दस्तावेज़ माँगा गया।","ਪਤੇ ਦੀ ਤਸਦੀਕ ਕਾਰਨ ਆਮਦਨ ਦਾ ਦਸਤਾਵੇਜ਼ ਮੰਗਿਆ ਗਿਆ।"),false,"POSSIBLE_ONLY",["F1"],"CAUSE_ASSUMPTION")], explanation:t("The dates establish that the address check came first. They do not say that it caused the later document request. Only II follows.","तारीखें बताती हैं कि पते की जाँच पहले हुई। इससे यह सिद्ध नहीं होता कि उसी के कारण बाद में दस्तावेज़ माँगा गया। केवल II सही है।","ਤਾਰੀਖਾਂ ਦੱਸਦੀਆਂ ਹਨ ਕਿ ਪਤੇ ਦੀ ਜਾਂਚ ਪਹਿਲਾਂ ਹੋਈ। ਇਸ ਨਾਲ ਇਹ ਸਾਬਤ ਨਹੀਂ ਹੁੰਦਾ ਕਿ ਇਸੇ ਕਾਰਨ ਬਾਅਦ ਵਿੱਚ ਦਸਤਾਵੇਜ਼ ਮੰਗਿਆ ਗਿਆ। ਕੇਵਲ II ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP014-COURSE-ENROLMENT", cpId:"SIF-CP014", difficulty:"MEDIUM", domain:"EDUCATION", mechanisms:["TIME_SEQUENCE"], statement:t("The college opened course registration on 1 August. It closed registration on 12 August. The first class was held on 20 August.","कॉलेज ने 1 अगस्त को पाठ्यक्रम के लिए पंजीकरण शुरू किया। पंजीकरण 12 अगस्त को बंद हुआ। पहली कक्षा 20 अगस्त को हुई।","ਕਾਲਜ ਨੇ 1 ਅਗਸਤ ਨੂੰ ਕੋਰਸ ਲਈ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਸ਼ੁਰੂ ਕੀਤੀ। ਰਜਿਸਟ੍ਰੇਸ਼ਨ 12 ਅਗਸਤ ਨੂੰ ਬੰਦ ਹੋਈ। ਪਹਿਲੀ ਕਲਾਸ 20 ਅਗਸਤ ਨੂੰ ਹੋਈ।"), facts:[fact("F1",t("Registration opened, then closed, and the first class followed.","ਪਹਿਲਾਂ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਖੁੱਲ੍ਹੀ, ਫਿਰ ਬੰਦ ਹੋਈ ਅਤੇ ਉਸ ਤੋਂ ਬਾਅਦ ਪਹਿਲੀ ਕਲਾਸ ਲੱਗੀ।","ਪਹਿਲਾਂ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਖੁੱਲ੍ਹੀ, ਫਿਰ ਬੰਦ ਹੋਈ ਅਤੇ ਉਸ ਤੋਂ ਬਾਅਦ ਪਹਿਲੀ ਕਲਾਸ ਲੱਗੀ।"))], candidates:[candidate("II",t("The first class was held after registration had closed.","ਪंजीकरण बंद होने के बाद पहली कक्षा हुई।","ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਬੰਦ ਹੋਣ ਤੋਂ ਬਾਅਦ ਪਹਿਲੀ ਕਲਾਸ ਲੱਗੀ।"),true,"CERTAIN",["F1"]),candidate("I",t("The college closed registration because the first class was ready to begin.","पहली कक्षा शुरू होने वाली थी, इसलिए कॉलेज ने पंजीकरण बंद किया।","ਪਹਿਲੀ ਕਲਾਸ ਸ਼ੁਰੂ ਹੋਣ ਵਾਲੀ ਸੀ, ਇਸ ਲਈ ਕਾਲਜ ਨੇ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਬੰਦ ਕੀਤੀ।"),false,"POSSIBLE_ONLY",["F1"],"CAUSE_ASSUMPTION")], explanation:t("The dates put the first class after registration closed. The notice gives no reason for closing registration, so II is not supported. Only II follows.","तारीखें बताती हैं कि पंजीकरण बंद होने के बाद पहली कक्षा हुई। पंजीकरण बंद करने का कारण नहीं दिया गया, इसलिए II सही नहीं है। केवल II सही है।","ਤਾਰੀਖਾਂ ਦੱਸਦੀਆਂ ਹਨ ਕਿ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਬੰਦ ਹੋਣ ਤੋਂ ਬਾਅਦ ਪਹਿਲੀ ਕਲਾਸ ਲੱਗੀ। ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਬੰਦ ਕਰਨ ਦਾ ਕਾਰਨ ਨਹੀਂ ਦਿੱਤਾ ਗਿਆ, ਇਸ ਲਈ II ਸਹੀ ਨਹੀਂ ਹੈ। ਕੇਵਲ II ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP014-WAREHOUSE-CHECK", cpId:"SIF-CP014", difficulty:"MEDIUM", domain:"BUSINESS", mechanisms:["TIME_SEQUENCE"], statement:t("The warehouse received a shipment on 3 February. Staff counted the cartons on 4 February. The supplier was notified of a shortage on 6 February.","गोदाम को 3 फरवरी को माल की खेप मिली। कर्मचारियों ने 4 फरवरी को डिब्बे गिने। 6 फरवरी को आपूर्तिकर्ता को कमी की सूचना दी गई।","ਗੋਦਾਮ ਨੂੰ 3 ਫਰਵਰੀ ਨੂੰ ਮਾਲ ਦੀ ਖੇਪ ਮਿਲੀ। ਕਰਮਚਾਰੀਆਂ ਨੇ 4 ਫਰਵਰੀ ਨੂੰ ਡੱਬੇ ਗਿਣੇ। 6 ਫਰਵਰੀ ਨੂੰ ਸਪਲਾਇਰ ਨੂੰ ਘਾਟ ਦੀ ਸੂਚਨਾ ਦਿੱਤੀ ਗਈ।"), facts:[fact("F1",t("Cartons were counted after receipt and before the supplier was notified.","ਡੱਬੇ ਮਿਲਣ ਤੋਂ ਬਾਅਦ ਅਤੇ ਸਪਲਾਇਰ ਨੂੰ ਸੂਚਿਤ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਗਿਣੇ ਗਏ।","ਡੱਬੇ ਮਿਲਣ ਤੋਂ ਬਾਅਦ ਅਤੇ ਸਪਲਾਇਰ ਨੂੰ ਸੂਚਿਤ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਗਿਣੇ ਗਏ।"))], candidates:[candidate("I",t("The shortage notice was sent after the cartons were counted.","ਡੱਬों की गिनती के बाद कमी की सूचना भेजी गई।","ਡੱਬਿਆਂ ਦੀ ਗਿਣਤੀ ਤੋਂ ਬਾਅਦ ਘਾਟ ਦੀ ਸੂਚਨਾ ਭੇਜੀ ਗਈ।"),true,"CERTAIN",["F1"]),candidate("II",t("The supplier caused the shortage by sending the shipment late.","आपूर्तिकर्ता ने खेप देर से भेजकर कमी पैदा की।","ਸਪਲਾਇਰ ਨੇ ਖੇਪ ਦੇਰੀ ਨਾਲ ਭੇਜ ਕੇ ਘਾਟ ਪੈਦਾ ਕੀਤੀ।"),false,"POSSIBLE_ONLY",["F1"],"CAUSE_ASSUMPTION")], explanation:t("The sequence is receipt, count and notice. Nothing says when delivery was due or who caused the shortage. Only I follows.","क्रम है: खेप मिलना, गिनती और सूचना। माल कब आना था या कमी किस कारण हुई, यह नहीं बताया गया। केवल I सही है।","ਕ੍ਰਮ ਹੈ: ਖੇਪ ਮਿਲਣਾ, ਗਿਣਤੀ ਅਤੇ ਸੂਚਨਾ। ਮਾਲ ਕਦੋਂ ਆਉਣਾ ਸੀ ਜਾਂ ਘਾਟ ਕਿਸ ਕਾਰਨ ਹੋਈ, ਇਹ ਨਹੀਂ ਦੱਸਿਆ ਗਿਆ। ਕੇਵਲ I ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP014-PATIENT-TRANSFER", cpId:"SIF-CP014", difficulty:"MEDIUM", domain:"HEALTHCARE", mechanisms:["TIME_SEQUENCE"], statement:t("The clinic registered a patient at 8:40 a.m. A doctor examined the patient at 9:15 a.m. The clinic arranged a transfer to another hospital at 9:50 a.m.","क्लिनिक ने सुबह 8:40 बजे मरीज का पंजीकरण किया। डॉक्टर ने 9:15 बजे मरीज की जाँच की। क्लिनिक ने 9:50 बजे दूसरे अस्पताल भेजने की व्यवस्था की।","ਕਲੀਨਿਕ ਨੇ ਸਵੇਰੇ 8:40 ਵਜੇ ਮਰੀਜ਼ ਦਾ ਨਾਂ ਦਰਜ ਕੀਤਾ। ਡਾਕਟਰ ਨੇ 9:15 ਵਜੇ ਮਰੀਜ਼ ਦੀ ਜਾਂਚ ਕੀਤੀ। ਕਲੀਨਿਕ ਨੇ 9:50 ਵਜੇ ਦੂਜੇ ਹਸਪਤਾਲ ਭੇਜਣ ਦਾ ਪ੍ਰਬੰਧ ਕੀਤਾ।"), facts:[fact("F1",t("The doctor examined the patient between registration and transfer arrangements.","ਮਰੀਜ਼ ਦੀ ਜਾਂਚ ਦਰਜ ਕਰਨ ਤੋਂ ਬਾਅਦ ਅਤੇ ਤਬਾਦਲੇ ਦੇ ਪ੍ਰਬੰਧ ਤੋਂ ਪਹਿਲਾਂ ਹੋਈ।","ਮਰੀਜ਼ ਦੀ ਜਾਂਚ ਦਰਜ ਕਰਨ ਤੋਂ ਬਾਅਦ ਅਤੇ ਭੇਜਣ ਦੇ ਪ੍ਰਬੰਧ ਤੋਂ ਪਹਿਲਾਂ ਹੋਈ।"))], candidates:[candidate("I",t("The examination took place before the clinic arranged the transfer.","क्लिनिक द्वारा भेजने की व्यवस्था करने से पहले जाँच हुई।","ਕਲੀਨਿਕ ਵੱਲੋਂ ਭੇਜਣ ਦਾ ਪ੍ਰਬੰਧ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਜਾਂਚ ਹੋਈ।"),true,"CERTAIN",["F1"]),candidate("II",t("The examination showed that the clinic could not treat the patient.","जाँच से पता चला कि क्लिनिक मरीज का इलाज नहीं कर सकता था।","ਜਾਂਚ ਤੋਂ ਪਤਾ ਲੱਗਾ ਕਿ ਕਲੀਨਿਕ ਮਰੀਜ਼ ਦਾ ਇਲਾਜ ਨਹੀਂ ਕਰ ਸਕਦਾ ਸੀ।"),false,"POSSIBLE_ONLY",["F1"],"UNSUPPORTED_DETAIL")], explanation:t("The times place the examination before the transfer arrangement. The reason for transfer is not stated, so II adds information not in the record. Only I follows.","समय बताते हैं कि भेजने की व्यवस्था से पहले जाँच हुई। भेजने का कारण नहीं बताया गया, इसलिए II में नई बात जोड़ी गई है। केवल I सही है।","ਸਮੇਂ ਦੱਸਦੇ ਹਨ ਕਿ ਭੇਜਣ ਦੇ ਪ੍ਰਬੰਧ ਤੋਂ ਪਹਿਲਾਂ ਜਾਂਚ ਹੋਈ। ਭੇਜਣ ਦਾ ਕਾਰਨ ਨਹੀਂ ਦੱਸਿਆ ਗਿਆ, ਇਸ ਲਈ II ਵਿੱਚ ਨਵੀਂ ਗੱਲ ਜੋੜੀ ਗਈ ਹੈ। ਕੇਵਲ I ਸਹੀ ਹੈ।") }),

  scenario({ id:"SIF-CP012-INSURANCE-RECEIPT", cpId:"SIF-CP012", difficulty:"MEDIUM", domain:"BUSINESS", mechanisms:["SUPPORT_THRESHOLD"], statement:t("The insurer confirmed that it received Dev's claim form and repair estimate. A surveyor's inspection is still pending. The message does not state whether the claim will be paid.","बीमा कंपनी ने देव के दावा-फॉर्म और मरम्मत के अनुमान मिलने की पुष्टि की। सर्वेक्षक का निरीक्षण अभी बाकी है। संदेश में यह नहीं बताया गया कि दावा मंजूर होगा या नहीं।","ਬੀਮਾ ਕੰਪਨੀ ਨੇ ਦੇਵ ਦਾ ਦਾਅਵਾ-ਫਾਰਮ ਅਤੇ ਮੁਰੰਮਤ ਦਾ ਅੰਦਾਜ਼ਾ ਮਿਲਣ ਦੀ ਪੁਸ਼ਟੀ ਕੀਤੀ। ਸਰਵੇਅਰ ਦੀ ਜਾਂਚ ਹਾਲੇ ਬਾਕੀ ਹੈ। ਸੁਨੇਹੇ ਵਿੱਚ ਨਹੀਂ ਦੱਸਿਆ ਕਿ ਦਾਅਵਾ ਮਨਜ਼ੂਰ ਹੋਵੇਗਾ ਜਾਂ ਨਹੀਂ।"), facts:[fact("F1",t("The insurer received the claim form and estimate; inspection is pending.","बीमा कंपनी को दावा-फॉर्म और अनुमान मिले; निरीक्षण बाकी है।","ਬੀਮਾ ਕੰਪਨੀ ਨੂੰ ਦਾਅਵਾ-ਫਾਰਮ ਅਤੇ ਅੰਦਾਜ਼ਾ ਮਿਲਿਆ; ਜਾਂਚ ਬਾਕੀ ਹੈ।"))], candidates:[candidate("I",t("The insurer has received Dev's claim documents.","बीमा कंपनी को देव के दावे के दस्तावेज़ मिल गए हैं।","ਬੀਮਾ ਕੰਪਨੀ ਨੂੰ ਦੇਵ ਦੇ ਦਾਅਵੇ ਦੇ ਦਸਤਾਵੇਜ਼ ਮਿਲ ਗਏ ਹਨ।"),true,"CERTAIN",["F1"]),candidate("II",t("Dev's repair costs will be reimbursed.","देव की मरम्मत का खर्च वापस मिलेगा।","ਦੇਵ ਦੀ ਮੁਰੰਮਤ ਦਾ ਖਰਚਾ ਵਾਪਸ ਮਿਲੇਗਾ।"),false,"POSSIBLE_ONLY",["F1"],"UNSUPPORTED_DETAIL")], explanation:t("The message confirms receipt of the documents, not approval of the claim. The inspection has not even taken place. Only I follows.","संदेश दस्तावेज़ मिलने की पुष्टि करता है, दावा मंजूर होने की नहीं। निरीक्षण भी अभी नहीं हुआ। केवल I सही है।","ਸੁਨੇਹਾ ਦਸਤਾਵੇਜ਼ ਮਿਲਣ ਦੀ ਪੁਸ਼ਟੀ ਕਰਦਾ ਹੈ, ਦਾਅਵਾ ਮਨਜ਼ੂਰ ਹੋਣ ਦੀ ਨਹੀਂ। ਜਾਂਚ ਵੀ ਹਾਲੇ ਨਹੀਂ ਹੋਈ। ਕੇਵਲ I ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP012-GRANT-APPLICATION", cpId:"SIF-CP012", difficulty:"HARD", domain:"PUBLIC_ADMINISTRATION", mechanisms:["SUPPORT_THRESHOLD"], statement:t("A farmer submitted a grant application with the land record and bank details. The office marked all three documents as received. The file has not yet been assessed against the grant conditions.","एक किसान ने भूमि रिकॉर्ड और बैंक विवरण के साथ अनुदान का आवेदन दिया। कार्यालय ने तीनों दस्तावेज़ मिलने का निशान लगाया। अनुदान की शर्तों के अनुसार फाइल की जाँच अभी नहीं हुई।","ਇੱਕ ਕਿਸਾਨ ਨੇ ਜ਼ਮੀਨੀ ਰਿਕਾਰਡ ਅਤੇ ਬੈਂਕ ਵੇਰਵਿਆਂ ਸਮੇਤ ਗ੍ਰਾਂਟ ਦੀ ਅਰਜ਼ੀ ਦਿੱਤੀ। ਦਫ਼ਤਰ ਨੇ ਤਿੰਨੇ ਦਸਤਾਵੇਜ਼ ਮਿਲਣ ਦੀ ਦਰਜ ਕੀਤੀ। ਗ੍ਰਾਂਟ ਦੀਆਂ ਸ਼ਰਤਾਂ ਅਨੁਸਾਰ ਫਾਈਲ ਦੀ ਜਾਂਚ ਹਾਲੇ ਨਹੀਂ ਹੋਈ।"), facts:[fact("F1",t("The office received the application and its three listed documents; eligibility assessment is pending.","दफ्तर को आवेदन और उसके तीनों दस्तावेज़ मिले; पात्रता की जाँच बाकी है।","ਦਫ਼ਤਰ ਨੂੰ ਅਰਜ਼ੀ ਅਤੇ ਇਸ ਦੇ ਤਿੰਨੇ ਦਸਤਾਵੇਜ਼ ਮਿਲੇ; ਯੋਗਤਾ ਦੀ ਜਾਂਚ ਬਾਕੀ ਹੈ।"))], candidates:[candidate("I",t("The farmer satisfies every condition for the grant.","किसान अनुदान की हर शर्त पूरी करता है।","ਕਿਸਾਨ ਗ੍ਰਾਂਟ ਦੀ ਹਰ ਸ਼ਰਤ ਪੂਰੀ ਕਰਦਾ ਹੈ।"),false,"POSSIBLE_ONLY",["F1"],"UNSUPPORTED_DETAIL"),candidate("II",t("The office has received the application and the three listed documents.","दफ्तर को आवेदन और बताए गए तीनों दस्तावेज़ मिल गए हैं।","ਦਫ਼ਤਰ ਨੂੰ ਅਰਜ਼ੀ ਅਤੇ ਦੱਸੇ ਤਿੰਨੇ ਦਸਤਾਵੇਜ਼ ਮਿਲ ਗਏ ਹਨ।"),true,"CERTAIN",["F1"])], explanation:t("Receipt of documents is established, but the office has not checked the grant conditions. Complete paperwork alone does not prove eligibility. Only II follows.","दस्तावेज़ मिलना तय है, लेकिन अनुदान की शर्तों की जाँच नहीं हुई। पूरे कागज़ होने से पात्रता सिद्ध नहीं होती। केवल II सही है।","ਦਸਤਾਵੇਜ਼ ਮਿਲਣੇ ਪੱਕੇ ਹਨ, ਪਰ ਗ੍ਰਾਂਟ ਦੀਆਂ ਸ਼ਰਤਾਂ ਦੀ ਜਾਂਚ ਨਹੀਂ ਹੋਈ। ਸਾਰੇ ਕਾਗਜ਼ ਹੋਣ ਨਾਲ ਯੋਗਤਾ ਸਾਬਤ ਨਹੀਂ ਹੁੰਦੀ। ਕੇਵਲ II ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP012-PROTOTYPE-TEST", cpId:"SIF-CP012", difficulty:"MEDIUM", domain:"BUSINESS", mechanisms:["SUPPORT_THRESHOLD"], statement:t("A prototype passed eight of ten checks in an internal test. Two checks remain open. The product team has not issued a release decision.","आंतरिक परीक्षण में एक नमूना उपकरण दस में से आठ जाँचों में पास हुआ। दो जाँचें बाकी हैं। उत्पाद दल ने उसे जारी करने का निर्णय नहीं लिया है।","ਅੰਦਰੂਨੀ ਜਾਂਚ ਵਿੱਚ ਇੱਕ ਨਮੂਨਾ ਉਪਕਰਣ ਦਸ ਵਿੱਚੋਂ ਅੱਠ ਜਾਂਚਾਂ ਵਿੱਚ ਪਾਸ ਹੋਇਆ। ਦੋ ਜਾਂਚਾਂ ਬਾਕੀ ਹਨ। ਉਤਪਾਦ ਟੀਮ ਨੇ ਇਸ ਨੂੰ ਜਾਰੀ ਕਰਨ ਦਾ ਫ਼ੈਸਲਾ ਨਹੀਂ ਕੀਤਾ।"), facts:[fact("F1",t("The prototype passed eight checks; two checks and the release decision are pending.","उपकरण आठ जाँचों में पास हुआ; दो जाँचें और जारी करने का निर्णय बाकी हैं।","ਉਪਕਰਣ ਅੱਠ ਜਾਂਚਾਂ ਵਿੱਚ ਪਾਸ ਹੋਇਆ; ਦੋ ਜਾਂਚਾਂ ਅਤੇ ਜਾਰੀ ਕਰਨ ਦਾ ਫ਼ੈਸਲਾ ਬਾਕੀ ਹਨ।"))], candidates:[candidate("I",t("The prototype passed eight checks in the internal test.","आंतरिक परीक्षण में उपकरण आठ जाँचों में पास हुआ।","ਅੰਦਰੂਨੀ ਜਾਂਚ ਵਿੱਚ ਉਪਕਰਣ ਅੱਠ ਜਾਂਚਾਂ ਵਿੱਚ ਪਾਸ ਹੋਇਆ।"),true,"CERTAIN",["F1"]),candidate("II",t("The product is ready for release.","उत्पाद जारी करने के लिए तैयार है।","ਉਤਪਾਦ ਜਾਰੀ ਕਰਨ ਲਈ ਤਿਆਰ ਹੈ।"),false,"POSSIBLE_ONLY",["F1"],"EXCESSIVE_CERTAINTY")], explanation:t("Eight passing checks are reported, but two checks and the release decision remain open. Readiness for release is not established. Only I follows.","आठ जाँचों में पास होना बताया गया है, लेकिन दो जाँचें और जारी करने का निर्णय बाकी हैं। उत्पाद जारी करने की तैयारी सिद्ध नहीं है। केवल I सही है।","ਅੱਠ ਜਾਂਚਾਂ ਵਿੱਚ ਪਾਸ ਹੋਣਾ ਦੱਸਿਆ ਗਿਆ ਹੈ, ਪਰ ਦੋ ਜਾਂਚਾਂ ਅਤੇ ਜਾਰੀ ਕਰਨ ਦਾ ਫ਼ੈਸਲਾ ਬਾਕੀ ਹੈ। ਉਤਪਾਦ ਜਾਰੀ ਕਰਨ ਦੀ ਤਿਆਰੀ ਸਾਬਤ ਨਹੀਂ। ਕੇਵਲ I ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP012-ADMISSION-CUTOFF", cpId:"SIF-CP012", difficulty:"HARD", domain:"EDUCATION", mechanisms:["SUPPORT_THRESHOLD"], statement:t("The admission notice sets a minimum score of 60 for the programme. Rohan scored 67. The programme has fewer seats than applicants, and the notice gives no final selection list.","प्रवेश सूचना में कार्यक्रम के लिए न्यूनतम 60 अंक तय हैं। रोहन को 67 अंक मिले। आवेदकों की तुलना में सीटें कम हैं और अंतिम चयन सूची जारी नहीं हुई।","ਦਾਖ਼ਲਾ ਸੂਚਨਾ ਵਿੱਚ ਪ੍ਰੋਗਰਾਮ ਲਈ ਘੱਟੋ-ਘੱਟ 60 ਅੰਕ ਰੱਖੇ ਗਏ ਹਨ। ਰੋਹਨ ਨੂੰ 67 ਅੰਕ ਮਿਲੇ। ਬਿਨੈਕਾਰਾਂ ਨਾਲੋਂ ਸੀਟਾਂ ਘੱਟ ਹਨ ਅਤੇ ਅੰਤਿਮ ਚੋਣ ਸੂਚੀ ਜਾਰੀ ਨਹੀਂ ਹੋਈ।"), facts:[fact("F1",t("Rohan scored above the stated minimum; the final selection list is unavailable.","रोहन के अंक तय न्यूनतम से अधिक हैं; अंतिम चयन सूची उपलब्ध नहीं है।","ਰੋਹਨ ਦੇ ਅੰਕ ਨਿਰਧਾਰਤ ਘੱਟੋ-ਘੱਟ ਤੋਂ ਵੱਧ ਹਨ; ਅੰਤਿਮ ਚੋਣ ਸੂਚੀ ਉਪਲਬਧ ਨਹੀਂ ਹੈ।"))], candidates:[candidate("I",t("Rohan has secured a seat in the programme.","रोहन को कार्यक्रम में सीट मिल गई है।","ਰੋਹਨ ਨੂੰ ਪ੍ਰੋਗਰਾਮ ਵਿੱਚ ਸੀਟ ਮਿਲ ਗਈ ਹੈ।"),false,"POSSIBLE_ONLY",["F1"],"UNSUPPORTED_DETAIL"),candidate("II",t("Rohan meets the stated minimum-score condition.","रोहन न्यूनतम अंक की बताई गई शर्त पूरी करता है।","ਰੋਹਨ ਘੱਟੋ-ਘੱਟ ਅੰਕਾਂ ਦੀ ਦੱਸੀ ਸ਼ਰਤ ਪੂਰੀ ਕਰਦਾ ਹੈ।"),true,"CERTAIN",["F1"])], explanation:t("His score is above the stated cutoff, so he meets that condition. Since seats are limited and no selection list is given, admission itself is not proved. Only II follows.","उसके अंक तय सीमा से अधिक हैं, इसलिए वह यह शर्त पूरी करता है। सीटें सीमित हैं और चयन सूची नहीं है, इसलिए प्रवेश मिलना सिद्ध नहीं है। केवल II सही है।","ਉਸ ਦੇ ਅੰਕ ਨਿਰਧਾਰਤ ਹੱਦ ਤੋਂ ਵੱਧ ਹਨ, ਇਸ ਲਈ ਉਹ ਇਹ ਸ਼ਰਤ ਪੂਰੀ ਕਰਦਾ ਹੈ। ਸੀਟਾਂ ਘੱਟ ਹਨ ਅਤੇ ਚੋਣ ਸੂਚੀ ਨਹੀਂ, ਇਸ ਲਈ ਦਾਖ਼ਲਾ ਮਿਲਣਾ ਸਾਬਤ ਨਹੀਂ। ਕੇਵਲ II ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP013-ONE-BLOCK-DRAIN", cpId:"SIF-CP013", difficulty:"MEDIUM", domain:"PUBLIC_ADMINISTRATION", mechanisms:["SCOPE_CONTROL"], statement:t("A drainage survey covered six lanes in East Block in September. Inspectors found silt in two drains. The report contains no observations from other blocks.","सितंबर में जल-निकासी सर्वेक्षण ईस्ट ब्लॉक की छह गलियों तक सीमित था। निरीक्षकों को दो नालियों में गाद मिली। रिपोर्ट में दूसरे ब्लॉकों की जानकारी नहीं है।","ਸਤੰਬਰ ਵਿੱਚ ਨਿਕਾਸੀ ਸਰਵੇਖਣ ਈਸਟ ਬਲਾਕ ਦੀਆਂ ਛੇ ਗਲੀਆਂ ਤੱਕ ਸੀਮਿਤ ਸੀ। ਜਾਂਚਕਰਤਾਵਾਂ ਨੂੰ ਦੋ ਨਾਲਿਆਂ ਵਿੱਚ ਗਾਰ ਮਿਲੀ। ਰਿਪੋਰਟ ਵਿੱਚ ਹੋਰ ਬਲਾਕਾਂ ਦੀ ਜਾਣਕਾਰੀ ਨਹੀਂ ਹੈ।"), facts:[fact("F1",t("Silt was found in two drains among six surveyed lanes in East Block.","ਈਸਟ ਬਲਾਕ ਦੀਆਂ ਛੇ ਜਾਂਚੀਆਂ ਗਲੀਆਂ ਵਿੱਚੋਂ ਦੋ ਨਾਲਿਆਂ ਵਿੱਚ ਗਾਰ ਮਿਲੀ।","ਈਸਟ ਬਲਾਕ ਦੀਆਂ ਛੇ ਜਾਂਚੀਆਂ ਗਲੀਆਂ ਵਿੱਚੋਂ ਦੋ ਨਾਲਿਆਂ ਵਿੱਚ ਗਾਰ ਮਿਲੀ।"))], candidates:[candidate("I",t("Two drains in the surveyed part of East Block contained silt.","सर्वेक्षित ईस्ट ब्लॉक की दो नालियों में गाद थी।","ਜਾਂਚੇ ਗਏ ਈਸਟ ਬਲਾਕ ਦੇ ਦੋ ਨਾਲਿਆਂ ਵਿੱਚ ਗਾਰ ਸੀ।"),true,"CERTAIN",["F1"]),candidate("II",t("Drains throughout the municipality were clogged in September.","सितंबर में पूरे नगर निगम क्षेत्र की नालियाँ बंद थीं।","ਸਤੰਬਰ ਵਿੱਚ ਪੂਰੇ ਨਗਰ ਨਿਗਮ ਦੀਆਂ ਨਾਲੀਆਂ ਜਾਮ ਸਨ।"),false,"POSSIBLE_ONLY",["F1"],"OVERGENERALISATION")], explanation:t("The report covers six lanes in one block and identifies two affected drains. It does not describe the rest of the municipality. Only I follows.","रिपोर्ट एक ब्लॉक की छह गलियों और दो नालियों तक सीमित है। नगर निगम के बाकी क्षेत्र का विवरण नहीं है। केवल I सही है।","ਰਿਪੋਰਟ ਇੱਕ ਬਲਾਕ ਦੀਆਂ ਛੇ ਗਲੀਆਂ ਅਤੇ ਦੋ ਨਾਲਿਆਂ ਤੱਕ ਸੀਮਿਤ ਹੈ। ਨਗਰ ਨਿਗਮ ਦੇ ਬਾਕੀ ਖੇਤਰ ਦਾ ਵੇਰਵਾ ਨਹੀਂ ਹੈ। ਕੇਵਲ I ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP013-CLASS-RESULT", cpId:"SIF-CP013", difficulty:"HARD", domain:"EDUCATION", mechanisms:["SCOPE_CONTROL"], statement:t("In one section of a school, 22 of 30 students passed the weekly mathematics quiz. The quiz covered fractions. The result sheet gives no marks for other sections or subjects.","स्कूल की एक कक्षा में 30 में से 22 विद्यार्थी साप्ताहिक गणित प्रश्नोत्तरी में पास हुए। प्रश्नोत्तरी भिन्नों पर थी। परिणाम-पत्र में दूसरी कक्षाओं या विषयों के अंक नहीं हैं।","ਸਕੂਲ ਦੀ ਇੱਕ ਜਮਾਤ ਵਿੱਚ 30 ਵਿੱਚੋਂ 22 ਵਿਦਿਆਰਥੀ ਹਫ਼ਤਾਵਾਰੀ ਗਣਿਤ ਕਵਿਜ਼ ਵਿੱਚ ਪਾਸ ਹੋਏ। ਕਵਿਜ਼ ਭਿੰਨਾਂ ਬਾਰੇ ਸੀ। ਨਤੀਜਾ-ਪੱਤਰ ਵਿੱਚ ਹੋਰ ਜਮਾਤਾਂ ਜਾਂ ਵਿਸ਼ਿਆਂ ਦੇ ਅੰਕ ਨਹੀਂ ਹਨ।"), facts:[fact("F1",t("Twenty-two of 30 students in one section passed a fractions quiz.","ਇੱਕ ਜਮਾਤ ਦੇ 30 ਵਿੱਚੋਂ 22 ਵਿਦਿਆਰਥੀ ਭਿੰਨਾਂ ਦੀ ਕਵਿਜ਼ ਵਿੱਚ ਪਾਸ ਹੋਏ।","ਇੱਕ ਜਮਾਤ ਦੇ 30 ਵਿੱਚੋਂ 22 ਵਿਦਿਆਰਥੀ ਭਿੰਨਾਂ ਦੀ ਕਵਿਜ਼ ਵਿੱਚ ਪਾਸ ਹੋਏ।"))], candidates:[candidate("I",t("Most students in the school have mastered mathematics.","स्कूल के अधिकांश विद्यार्थियों ने गणित में महारत हासिल कर ली है।","ਸਕੂਲ ਦੇ ਬਹੁਤੇ ਵਿਦਿਆਰਥੀਆਂ ਨੇ ਗਣਿਤ ਵਿੱਚ ਮੁਹਾਰਤ ਹਾਸਲ ਕਰ ਲਈ ਹੈ।"),false,"POSSIBLE_ONLY",["F1"],"OVERGENERALISATION"),candidate("II",t("A majority of students in that section passed the fractions quiz.","उस कक्षा के अधिकांश विद्यार्थी भिन्नों की प्रश्नोत्तरी में पास हुए।","ਉਸ ਜਮਾਤ ਦੇ ਬਹੁਤੇ ਵਿਦਿਆਰਥੀ ਭਿੰਨਾਂ ਦੀ ਕਵਿਜ਼ ਵਿੱਚ ਪਾਸ ਹੋਏ।"),true,"CERTAIN",["F1"])], explanation:t("The result shows a majority passing one quiz in one section. It does not show mastery of all mathematics across the school. Only II follows.","नतीजा एक कक्षा की एक प्रश्नोत्तरी में बहुमत के पास होने का है। इससे पूरे स्कूल में गणित की महारत सिद्ध नहीं होती। केवल II सही है।","ਨਤੀਜਾ ਇੱਕ ਜਮਾਤ ਦੀ ਇੱਕ ਕਵਿਜ਼ ਵਿੱਚ ਬਹੁਮਤ ਦੇ ਪਾਸ ਹੋਣ ਦਾ ਹੈ। ਇਸ ਨਾਲ ਪੂਰੇ ਸਕੂਲ ਵਿੱਚ ਗਣਿਤ ਦੀ ਮੁਹਾਰਤ ਸਾਬਤ ਨਹੀਂ ਹੁੰਦੀ। ਕੇਵਲ II ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP013-ONE-DAY-COUNTER", cpId:"SIF-CP013", difficulty:"MEDIUM", domain:"PUBLIC_ADMINISTRATION", mechanisms:["SCOPE_CONTROL"], statement:t("The passport counter at one district office processed 96 applications on Tuesday. A computer outage stopped work for 40 minutes that afternoon. The office report gives no figures for other days or counters.","एक जिला कार्यालय के पासपोर्ट काउंटर ने मंगलवार को 96 आवेदन निपटाए। मंगलवार दोपहर कंप्यूटर बंद होने से 40 मिनट काम रुका। कार्यालय रिपोर्ट में दूसरे दिनों या काउंटरों के आंकड़े नहीं हैं।","ਇੱਕ ਜ਼ਿਲ੍ਹਾ ਦਫ਼ਤਰ ਦੇ ਪਾਸਪੋਰਟ ਕਾਊਂਟਰ ਨੇ ਮੰਗਲਵਾਰ ਨੂੰ 96 ਅਰਜ਼ੀਆਂ ਨਿਪਟਾਈਆਂ। ਦੁਪਹਿਰ ਨੂੰ ਕੰਪਿਊਟਰ ਬੰਦ ਹੋਣ ਕਰਕੇ 40 ਮਿੰਟ ਕੰਮ ਰੁਕਿਆ। ਦਫ਼ਤਰ ਦੀ ਰਿਪੋਰਟ ਵਿੱਚ ਹੋਰ ਦਿਨਾਂ ਜਾਂ ਕਾਊਂਟਰਾਂ ਦੇ ਅੰਕੜੇ ਨਹੀਂ ਹਨ।"), facts:[fact("F1",t("The counter processed 96 applications on Tuesday and paused for 40 minutes.","ਕਾਊਂਟਰ ਨੇ ਮੰਗਲਵਾਰ ਨੂੰ 96 ਅਰਜ਼ੀਆਂ ਨਿਪਟਾਈਆਂ ਅਤੇ 40 ਮਿੰਟ ਕੰਮ ਰੁਕਿਆ।","ਕਾਊਂਟਰ ਨੇ ਮੰਗਲਵਾਰ ਨੂੰ 96 ਅਰਜ਼ੀਆਂ ਨਿਪਟਾਈਆਂ ਅਤੇ 40 ਮਿੰਟ ਕੰਮ ਰੁਕਿਆ।"))], candidates:[candidate("I",t("The counter processed 96 applications on Tuesday.","काउंटर ने मंगलवार को 96 आवेदन निपटाए।","ਕਾਊਂਟਰ ਨੇ ਮੰਗਲਵਾਰ ਨੂੰ 96 ਅਰਜ਼ੀਆਂ ਨਿਪਟਾਈਆਂ।"),true,"CERTAIN",["F1"]),candidate("II",t("The district office's passport service is usually interrupted by outages.","जिला कार्यालय की पासपोर्ट सेवा आम तौर पर तकनीकी खराबी से रुकती है।","ਜ਼ਿਲ੍ਹਾ ਦਫ਼ਤਰ ਦੀ ਪਾਸਪੋਰਟ ਸੇਵਾ ਆਮ ਤੌਰ 'ਤੇ ਤਕਨੀਕੀ ਖ਼ਰਾਬੀ ਕਰਕੇ ਰੁਕਦੀ ਹੈ।"),false,"POSSIBLE_ONLY",["F1"],"TIME_DISTORTION")], explanation:t("The report describes one counter and one Tuesday. It does not establish how often outages occur or what happens at other counters. Only I follows.","रिपोर्ट एक काउंटर और एक मंगलवार की है। इससे खराबी की आवृत्ति या दूसरे काउंटरों की स्थिति सिद्ध नहीं होती। केवल I सही है।","ਰਿਪੋਰਟ ਇੱਕ ਕਾਊਂਟਰ ਅਤੇ ਇੱਕ ਮੰਗਲਵਾਰ ਦੀ ਹੈ। ਇਸ ਨਾਲ ਖ਼ਰਾਬੀ ਕਿੰਨੀ ਵਾਰ ਹੁੰਦੀ ਹੈ ਜਾਂ ਹੋਰ ਕਾਊਂਟਰਾਂ ਦੀ ਹਾਲਤ ਸਾਬਤ ਨਹੀਂ ਹੁੰਦੀ। ਕੇਵਲ I ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP013-COASTAL-SAMPLE", cpId:"SIF-CP013", difficulty:"HARD", domain:"SURVEY", mechanisms:["SCOPE_CONTROL"], statement:t("A survey interviewed 180 households in three coastal villages about storm warnings. Most respondents said they had received the last warning. The survey did not cover inland villages or earlier storms.","तूफानी चेतावनियों पर एक सर्वेक्षण में तटीय तीन गाँवों के 180 परिवारों से बात की गई। अधिकांश उत्तरदाताओं ने कहा कि उन्हें पिछली चेतावनी मिली थी। सर्वेक्षण में अंदरूनी गाँव या पुराने तूफान शामिल नहीं थे।","ਤੂਫ਼ਾਨੀ ਚੇਤਾਵਨੀਆਂ ਬਾਰੇ ਇੱਕ ਸਰਵੇਖਣ ਵਿੱਚ ਤੱਟੀ ਤਿੰਨ ਪਿੰਡਾਂ ਦੇ 180 ਪਰਿਵਾਰਾਂ ਨਾਲ ਗੱਲ ਕੀਤੀ ਗਈ। ਬਹੁਤੇ ਜਵਾਬਦਾਤਾਵਾਂ ਨੇ ਕਿਹਾ ਕਿ ਉਨ੍ਹਾਂ ਨੂੰ ਪਿਛਲੀ ਚੇਤਾਵਨੀ ਮਿਲੀ ਸੀ। ਅੰਦਰਲੇ ਪਿੰਡ ਜਾਂ ਪੁਰਾਣੇ ਤੂਫ਼ਾਨ ਸਰਵੇਖਣ ਵਿੱਚ ਸ਼ਾਮਲ ਨਹੀਂ ਸਨ।"), facts:[fact("F1",t("Most surveyed households in three coastal villages reported receiving the last warning.","ਤੱਟੀ ਤਿੰਨ ਪਿੰਡਾਂ ਦੇ ਸਰਵੇਖਣ ਕੀਤੇ ਬਹੁਤੇ ਪਰਿਵਾਰਾਂ ਨੇ ਦੱਸਿਆ ਕਿ ਉਨ੍ਹਾਂ ਨੂੰ ਪਿਛਲੀ ਚੇਤਾਵਨੀ ਮਿਲੀ ਸੀ।","ਤੱਟੀ ਤਿੰਨ ਪਿੰਡਾਂ ਦੇ ਸਰਵੇਖਣ ਕੀਤੇ ਬਹੁਤੇ ਪਰਿਵਾਰਾਂ ਨੇ ਦੱਸਿਆ ਕਿ ਉਨ੍ਹਾਂ ਨੂੰ ਪਿਛਲੀ ਚੇਤਾਵਨੀ ਮਿਲੀ ਸੀ।"))], candidates:[candidate("I",t("Most households in the region receive every storm warning.","क्षेत्र के अधिकांश परिवारों को हर तूफान की चेतावनी मिलती है।","ਖੇਤਰ ਦੇ ਬਹੁਤੇ ਪਰਿਵਾਰਾਂ ਨੂੰ ਹਰ ਤੂਫ਼ਾਨ ਦੀ ਚੇਤਾਵਨੀ ਮਿਲਦੀ ਹੈ।"),false,"POSSIBLE_ONLY",["F1"],"OVERGENERALISATION"),candidate("II",t("Most surveyed households in those coastal villages reported receiving the last warning.","ਉਨ੍ਹਾਂ ਤੱਟੀ ਪਿੰਡਾਂ ਦੇ ਸਰਵੇਖਣ ਕੀਤੇ ਬਹੁਤੇ ਪਰਿਵਾਰਾਂ ਨੇ ਦੱਸਿਆ ਕਿ ਉਨ੍ਹਾਂ ਨੂੰ ਪਿਛਲੀ ਚੇਤਾਵਨੀ ਮਿਲੀ ਸੀ।","ਉਨ੍ਹਾਂ ਤੱਟੀ ਪਿੰਡਾਂ ਦੇ ਸਰਵੇਖਣ ਕੀਤੇ ਬਹੁਤੇ ਪਰਿਵਾਰਾਂ ਨੇ ਦੱਸਿਆ ਕਿ ਉਨ੍ਹਾਂ ਨੂੰ ਪਿਛਲੀ ਚੇਤਾਵਨੀ ਮਿਲੀ ਸੀ।"),true,"CERTAIN",["F1"])], explanation:t("The finding is limited to surveyed households in three coastal villages and one warning. It cannot establish coverage across the region or for every storm. Only II follows.","नतीजा तीन तटीय गाँवों के सर्वेक्षित परिवारों और एक चेतावनी तक सीमित है। इससे पूरे क्षेत्र या हर तूफान की स्थिति सिद्ध नहीं होती। केवल II सही है।","ਨਤੀਜਾ ਤੱਟੀ ਤਿੰਨ ਪਿੰਡਾਂ ਦੇ ਸਰਵੇਖਣ ਕੀਤੇ ਪਰਿਵਾਰਾਂ ਅਤੇ ਇੱਕ ਚੇਤਾਵਨੀ ਤੱਕ ਸੀਮਿਤ ਹੈ। ਇਸ ਨਾਲ ਪੂਰੇ ਖੇਤਰ ਜਾਂ ਹਰ ਤੂਫ਼ਾਨ ਦੀ ਹਾਲਤ ਸਾਬਤ ਨਹੀਂ ਹੁੰਦੀ। ਕੇਵਲ II ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP014-METER-INSPECTION", cpId:"SIF-CP014", difficulty:"MEDIUM", domain:"EVERYDAY", mechanisms:["TIME_SEQUENCE"], statement:t("A technician recorded a high meter reading at 11:10 a.m. The resident switched off the main appliance at 11:25 a.m. A second reading was taken at 11:40 a.m.","तकनीशियन ने सुबह 11:10 बजे मीटर की ऊँची रीडिंग दर्ज की। निवासी ने 11:25 बजे मुख्य उपकरण बंद किया। दूसरी रीडिंग 11:40 बजे ली गई।","ਟੈਕਨੀਸ਼ੀਅਨ ਨੇ ਸਵੇਰੇ 11:10 ਵਜੇ ਮੀਟਰ ਦੀ ਵੱਧ ਰੀਡਿੰਗ ਦਰਜ ਕੀਤੀ। ਵਸਨੀਕ ਨੇ 11:25 ਵਜੇ ਮੁੱਖ ਉਪਕਰਣ ਬੰਦ ਕੀਤਾ। ਦੂਜੀ ਰੀਡਿੰਗ 11:40 ਵਜੇ ਲਈ ਗਈ।"), facts:[fact("F1",t("The appliance was switched off after the first reading and before the second.","ਪਹਿਲੀ ਰੀਡਿੰਗ ਤੋਂ ਬਾਅਦ ਅਤੇ ਦੂਜੀ ਤੋਂ ਪਹਿਲਾਂ ਉਪਕਰਣ ਬੰਦ ਕੀਤਾ ਗਿਆ।","ਪਹਿਲੀ ਰੀਡਿੰਗ ਤੋਂ ਬਾਅਦ ਅਤੇ ਦੂਜੀ ਤੋਂ ਪਹਿਲਾਂ ਉਪਕਰਣ ਬੰਦ ਕੀਤਾ ਗਿਆ।"))], candidates:[candidate("I",t("The second reading was taken after the appliance was switched off.","दूसरी रीडिंग उपकरण बंद होने के बाद ली गई।","ਦੂਜੀ ਰੀਡਿੰਗ ਉਪਕਰਣ ਬੰਦ ਹੋਣ ਤੋਂ ਬਾਅਦ ਲਈ ਗਈ।"),true,"CERTAIN",["F1"]),candidate("II",t("The appliance caused the high first reading.","पहली ऊँची रीडिंग उसी उपकरण के कारण थी।","ਪਹਿਲੀ ਵੱਧ ਰੀਡਿੰਗ ਉਸੇ ਉਪਕਰਣ ਕਰਕੇ ਸੀ।"),false,"POSSIBLE_ONLY",["F1"],"CAUSE_ASSUMPTION")], explanation:t("The times establish that the second reading came after the appliance was switched off. They do not identify the cause of the earlier high reading. Only I follows.","समय बताते हैं कि दूसरी रीडिंग उपकरण बंद होने के बाद ली गई। पहले ऊँचे माप का कारण नहीं बताया गया। केवल I सही है।","ਸਮੇਂ ਦੱਸਦੇ ਹਨ ਕਿ ਦੂਜੀ ਰੀਡਿੰਗ ਉਪਕਰਣ ਬੰਦ ਹੋਣ ਤੋਂ ਬਾਅਦ ਲਈ ਗਈ। ਪਹਿਲੇ ਵੱਧ ਮਾਪ ਦਾ ਕਾਰਨ ਨਹੀਂ ਦੱਸਿਆ ਗਿਆ। ਕੇਵਲ I ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP014-CERTIFICATE-ISSUE", cpId:"SIF-CP014", difficulty:"HARD", domain:"WORKPLACE", mechanisms:["TIME_SEQUENCE"], statement:t("Meera completed the safety module on 4 April. Her supervisor signed the attendance record on 6 April. The training office issued her certificate on 9 April.","मीरा ने 4 अप्रैल को सुरक्षा मॉड्यूल पूरा किया। उसके पर्यवेक्षक ने 6 अप्रैल को उपस्थिति रिकॉर्ड पर हस्ताक्षर किए। प्रशिक्षण कार्यालय ने 9 अप्रैल को प्रमाणपत्र जारी किया।","ਮੀਰਾ ਨੇ 4 ਅਪ੍ਰੈਲ ਨੂੰ ਸੁਰੱਖਿਆ ਮੋਡੀਊਲ ਪੂਰਾ ਕੀਤਾ। ਉਸ ਦੇ ਨਿਗਰਾਨ ਨੇ 6 ਅਪ੍ਰੈਲ ਨੂੰ ਹਾਜ਼ਰੀ ਰਿਕਾਰਡ 'ਤੇ ਦਸਤਖ਼ਤ ਕੀਤੇ। ਸਿਖਲਾਈ ਦਫ਼ਤਰ ਨੇ 9 ਅਪ੍ਰੈਲ ਨੂੰ ਸਰਟੀਫਿਕੇਟ ਜਾਰੀ ਕੀਤਾ।"), facts:[fact("F1",t("The supervisor signed the record after module completion and before certificate issue.","ਮੋਡੀਊਲ ਪੂਰਾ ਹੋਣ ਤੋਂ ਬਾਅਦ ਅਤੇ ਸਰਟੀਫਿਕੇਟ ਜਾਰੀ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਨਿਗਰਾਨ ਨੇ ਰਿਕਾਰਡ 'ਤੇ ਦਸਤਖ਼ਤ ਕੀਤੇ।","ਮੋਡੀਊਲ ਪੂਰਾ ਹੋਣ ਤੋਂ ਬਾਅਦ ਅਤੇ ਸਰਟੀਫਿਕੇਟ ਜਾਰੀ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਨਿਗਰਾਨ ਨੇ ਰਿਕਾਰਡ 'ਤੇ ਦਸਤਖ਼ਤ ਕੀਤੇ।"))], candidates:[candidate("I",t("The certificate was issued after the attendance record was signed.","ਹਾਜ਼ਰੀ ਰਿਕਾਰਡ 'ਤੇ ਦਸਤਖ਼ਤ ਹੋਣ ਤੋਂ ਬਾਅਦ ਸਰਟੀਫਿਕੇਟ ਜਾਰੀ ਹੋਇਆ।","ਹਾਜ਼ਰੀ ਰਿਕਾਰਡ 'ਤੇ ਦਸਤਖ਼ਤ ਹੋਣ ਤੋਂ ਬਾਅਦ ਸਰਟੀਫਿਕੇਟ ਜਾਰੀ ਹੋਇਆ।"),true,"CERTAIN",["F1"]),candidate("II",t("The supervisor's signature caused the office to issue the certificate.","ਨਿਗਰਾਨ ਦੇ ਦਸਤਖ਼ਤ ਕਰਕੇ ਦਫ਼ਤਰ ਨੇ ਸਰਟੀਫਿਕੇਟ ਜਾਰੀ ਕੀਤਾ।","ਨਿਗਰਾਨ ਦੇ ਦਸਤਖ਼ਤ ਕਰਕੇ ਦਫ਼ਤਰ ਨੇ ਸਰਟੀਫਿਕੇਟ ਜਾਰੀ ਕੀਤਾ।"),false,"POSSIBLE_ONLY",["F1"],"CAUSE_ASSUMPTION")], explanation:t("The dates place the signature before certificate issue. They do not state that the signature alone caused the office's decision. Only I follows.","तारीखें हस्ताक्षर को प्रमाणपत्र जारी होने से पहले रखती हैं। यह नहीं बताया गया कि केवल हस्ताक्षर के कारण प्रमाणपत्र जारी हुआ। केवल I सही है।","ਤਾਰੀਖਾਂ ਦਸਤਖ਼ਤ ਨੂੰ ਸਰਟੀਫਿਕੇਟ ਜਾਰੀ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਰੱਖਦੀਆਂ ਹਨ। ਇਹ ਨਹੀਂ ਦੱਸਿਆ ਗਿਆ ਕਿ ਸਿਰਫ਼ ਦਸਤਖ਼ਤ ਕਾਰਨ ਸਰਟੀਫਿਕੇਟ ਜਾਰੀ ਹੋਇਆ। ਕੇਵਲ I ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP014-COMPLAINT-CLOSURE", cpId:"SIF-CP014", difficulty:"MEDIUM", domain:"PUBLIC_ADMINISTRATION", mechanisms:["TIME_SEQUENCE"], statement:t("A resident lodged a water-supply complaint on 13 December. The control room forwarded it to the repair team on 14 December. The complaint was marked closed on 16 December.","एक निवासी ने 13 दिसंबर को जल-आपूर्ति की शिकायत दर्ज की। नियंत्रण कक्ष ने 14 दिसंबर को उसे मरम्मत दल को भेजा। शिकायत 16 दिसंबर को बंद की गई।","ਇੱਕ ਵਸਨੀਕ ਨੇ 13 ਦਸੰਬਰ ਨੂੰ ਪਾਣੀ ਦੀ ਸਪਲਾਈ ਬਾਰੇ ਸ਼ਿਕਾਇਤ ਦਰਜ ਕੀਤੀ। ਕੰਟਰੋਲ ਰੂਮ ਨੇ 14 ਦਸੰਬਰ ਨੂੰ ਇਹ ਮੁਰੰਮਤ ਟੀਮ ਨੂੰ ਭੇਜੀ। ਸ਼ਿਕਾਇਤ 16 ਦਸੰਬਰ ਨੂੰ ਬੰਦ ਕੀਤੀ ਗਈ।"), facts:[fact("F1",t("The complaint was forwarded after filing and marked closed later.","ਸ਼ਿਕਾਇਤ ਦਰਜ ਹੋਣ ਤੋਂ ਬਾਅਦ ਅੱਗੇ ਭੇਜੀ ਗਈ ਅਤੇ ਬਾਅਦ ਵਿੱਚ ਬੰਦ ਕੀਤੀ ਗਈ।","ਸ਼ਿਕਾਇਤ ਦਰਜ ਹੋਣ ਤੋਂ ਬਾਅਦ ਅੱਗੇ ਭੇਜੀ ਗਈ ਅਤੇ ਬਾਅਦ ਵਿੱਚ ਬੰਦ ਕੀਤੀ ਗਈ।"))], candidates:[candidate("I",t("The complaint was forwarded before it was marked closed.","शिकायत बंद होने से पहले आगे भेजी गई।","ਸ਼ਿਕਾਇਤ ਬੰਦ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਅੱਗੇ ਭੇਜੀ ਗਈ।"),true,"CERTAIN",["F1"]),candidate("II",t("The repair team resolved the water-supply problem.","मरम्मत दल ने जल-आपूर्ति की समस्या हल कर दी।","ਮੁਰੰਮਤ ਟੀਮ ਨੇ ਪਾਣੀ ਦੀ ਸਮੱਸਿਆ ਹੱਲ ਕਰ ਦਿੱਤੀ।"),false,"POSSIBLE_ONLY",["F1"],"UNSUPPORTED_DETAIL")], explanation:t("The log shows the order of filing, forwarding and closure. It does not describe the repair or confirm that supply was restored. Only I follows.","लॉग शिकायत दर्ज होने, आगे भेजने और बंद होने का क्रम बताता है। मरम्मत या जल-आपूर्ति बहाल होने का विवरण नहीं है। केवल I सही है।","ਰਿਕਾਰਡ ਸ਼ਿਕਾਇਤ ਦਰਜ ਹੋਣ, ਅੱਗੇ ਭੇਜਣ ਅਤੇ ਬੰਦ ਹੋਣ ਦਾ ਕ੍ਰਮ ਦੱਸਦਾ ਹੈ। ਮੁਰੰਮਤ ਜਾਂ ਪਾਣੀ ਦੀ ਸਪਲਾਈ ਬਹਾਲ ਹੋਣ ਦਾ ਵੇਰਵਾ ਨਹੀਂ ਹੈ। ਕੇਵਲ I ਸਹੀ ਹੈ।") }),
  scenario({ id:"SIF-CP014-CROP-INSPECTION", cpId:"SIF-CP014", difficulty:"MEDIUM", domain:"PUBLIC_ADMINISTRATION", mechanisms:["TIME_SEQUENCE"], statement:t("An agriculture officer inspected a field on 17 August. The farmer submitted a damage estimate on 19 August. The department recorded the estimate on 21 August.","कृषि अधिकारी ने 17 अगस्त को खेत का निरीक्षण किया। किसान ने 19 अगस्त को नुकसान का अनुमान जमा किया। विभाग ने 21 अगस्त को अनुमान दर्ज किया।","ਖੇਤੀਬਾੜੀ ਅਧਿਕਾਰੀ ਨੇ 17 ਅਗਸਤ ਨੂੰ ਖੇਤ ਦੀ ਜਾਂਚ ਕੀਤੀ। ਕਿਸਾਨ ਨੇ 19 ਅਗਸਤ ਨੂੰ ਨੁਕਸਾਨ ਦਾ ਅੰਦਾਜ਼ਾ ਦਿੱਤਾ। ਵਿਭਾਗ ਨੇ 21 ਅਗਸਤ ਨੂੰ ਅੰਦਾਜ਼ਾ ਦਰਜ ਕੀਤਾ।"), facts:[fact("F1",t("The field inspection preceded the farmer's estimate and its recording.","ਖੇਤ ਦੀ ਜਾਂਚ ਕਿਸਾਨ ਦੇ ਅੰਦਾਜ਼ੇ ਅਤੇ ਇਸ ਦੀ ਦਰਜ ਤੋਂ ਪਹਿਲਾਂ ਹੋਈ।","ਖੇਤ ਦੀ ਜਾਂਚ ਕਿਸਾਨ ਦੇ ਅੰਦਾਜ਼ੇ ਅਤੇ ਇਸ ਦੀ ਦਰਜ ਤੋਂ ਪਹਿਲਾਂ ਹੋਈ।"))], candidates:[candidate("I",t("The department recorded the estimate after the field inspection.","खेत के निरीक्षण के बाद विभाग ने अनुमान दर्ज किया।","ਖੇਤ ਦੀ ਜਾਂਚ ਤੋਂ ਬਾਅਦ ਵਿਭਾਗ ਨੇ ਅੰਦਾਜ਼ਾ ਦਰਜ ਕੀਤਾ।"),true,"CERTAIN",["F1"]),candidate("II",t("The inspection confirmed that the crop damage was caused by drought.","निरीक्षण से सिद्ध हुआ कि फसल का नुकसान सूखे से हुआ।","ਜਾਂਚ ਨਾਲ ਸਾਬਤ ਹੋਇਆ ਕਿ ਫ਼ਸਲ ਦਾ ਨੁਕਸਾਨ ਸੋਕਾ ਪੈਣ ਕਰਕੇ ਹੋਇਆ।"),false,"POSSIBLE_ONLY",["F1"],"CAUSE_ASSUMPTION")], explanation:t("The dates establish that the inspection came before the estimate and its recording. They do not give the cause of crop damage. Only I follows.","तारीखें बताती हैं कि निरीक्षण, अनुमान और उसके दर्ज होने से पहले हुआ। फसल के नुकसान का कारण नहीं दिया गया। केवल I सही है।","ਤਾਰੀਖਾਂ ਦੱਸਦੀਆਂ ਹਨ ਕਿ ਜਾਂਚ ਅੰਦਾਜ਼ੇ ਅਤੇ ਇਸ ਦੀ ਦਰਜ ਤੋਂ ਪਹਿਲਾਂ ਹੋਈ। ਫ਼ਸਲ ਦੇ ਨੁਕਸਾਨ ਦਾ ਕਾਰਨ ਨਹੀਂ ਦਿੱਤਾ ਗਿਆ। ਕੇਵਲ I ਸਹੀ ਹੈ।") }),

];

